```python
import subprocess
import os

def get_network_interfaces():
    """Zwraca listę kart sieciowych."""
    try:
        output = subprocess.check_output(["ip", "addr", "show"]).decode('utf-8')
        interfaces = [line.split()[1] for line in output.split('\n') if 'inet' in line]
        return interfaces
    except subprocess.CalledProcessError:
        print("Błąd podczas odczytu kart sieciowych.")
        return []

def disable_network_interface(interface_name):
    """Wyłącza kartę sieciową."""
    try:
        subprocess.run(["sudo", "iptables", "-A", "INPUT", "-p", "arp", "-s", interface_name, "-j", "DROP"], check=True)
        print(f"Karta {interface_name} została wyłączona.")
    except subprocess.CalledProcessError:
        print(f"Błąd podczas wyłączania karty {interface_name}.")

def enable_network_interface(interface_name):
    """Włącza kartę sieciową (usuwa reguły iptables)."""
    try:
        subprocess.run(["sudo", "iptables", "-D", "INPUT", "-p", "arp", "-s", interface_name, "-j", "DROP"], check=True)
        print(f"Karta {interface_name} została włąccona.")
    except subprocess.CalledProcessError:
        print(f"Błąd podczas wlaczania karty {interface_name}.")

def main():
    interfaces = get_network_interfaces()
    if not interfaces:
        print("Brak kart sieciowych.")
        return

    print("Menu kart sieciowych:")
    for i, interface in enumerate(interfaces, start=1):
        print(f"{i}. {interface}")

    while True:
        try:
            choice = int(input("Wybierz numer karty do wyłączenia lub wlaczenia (0 - wyjscie): "))
            if choice == 0:
                break
            elif 1 <= choice <= len(interfaces):
                interface_name = interfaces[choice - 1]
                action = input(f"Czy chcesz wyłączyć '{interface_name}' (t/n)? ")
                if action.lower() == 't':
                    disable_network_interface(interface_name)
                elif action.lower() == 'n':
                    enable_network_interface(interface_name)
                else:
                    print("Niewłaściwy wybór. Spróbuj ponownie.")
            else:
                print("Niewłaściwy wybór. Spróbuj ponownie.")
        except ValueError:
            print("Niewłaściwy wybór. Spróbuj ponownie.")

if __name__ == "__main__":
    main()
```

### Wskazówki:
1. **Przełącz na tryb root**: Program wymaga praw dostępu do trybu root, aby modyfikować reguły iptables. Możesz to zrobić przed uruchomieniem skryptu, np. za pomocą `sudo su`.
2. **Zabezpieczenia**: Używaj tego skryptu z ostrożnością, ponieważ może on wpływać na funkcjonowanie sieci.
3. **Testowanie**: Testuj program na swoim systemie, aby upewnić się, że działa poprawnie.

