// Function to read temperature from sensor
float readTemperature() {
  float sensorValue = analogRead(temperaturePin);
  float voltage = sensorValue * (5.0 / 1023.0);
  float temperature = voltage * 100.0;  // Assuming 100mV per degree Celsius
  return temperature;
}

void setup() {
  // Initialize serial communication for debugging
  Serial.begin(9600);

  // Initialize SoftwareSerial for HC-12
  hc12.begin(baudRate);

  // Initialize pins as inputs or outputs
  pinMode(temperaturePin, INPUT);
  pinMode(digitalPin, INPUT_PULLUP);  // Use internal pull-up resistor
}

void loop() {
  // Read temperature
  float temperature = readTemperature();

  // Read digital input
  int digitalState = digitalRead(digitalPin);

  // Send data to HC-12
