  // Send data to Serial Monitor for debugging
  Serial.print("Temperature: ");
  Serial.print(temperature);
  Serial.print("°C, Digital Input: ");
  Serial.println(digitalState);

  // Wait for a short period
  delay(1000);
}

// Function to send data to HC-12
void sendToHC12(float temperature, int digitalState) {
  // Send temperature data
