以下是使用C语言将两个升序链表合并成一个新的升序链表的代码示例：

```c
#include <stdio.h>
#include <stdlib.h>

// 定义链表节点结构体
typedef struct Node {
    int data;
    struct Node* next;
} Node;

// 创建一个新的节点
Node* createNode(int data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

// 合并两个升序链表
Node* mergeSortedLists(Node* head1, Node* head2) {
    // 创建一个新的链表来存储合并结果
    Node* dummy = createNode(0);
    Node* current = dummy;
    Node* temp1 = head1;
    Node* temp2 = head2;

    // 合并两个链表
    while (temp1 != NULL && temp2 != NULL) {
        if (temp1->data < temp2->data) {
            current->next = temp1;
            temp1 = temp1->next;
        } else {
            current->next = temp2;
            temp2 = temp2->next;
        }
        current = current->next;
    }

    // 如果一个链表还有剩余节点，则将剩余节点连接到合并结果的末尾
    if (temp1 != NULL) {
        current->next = temp1;
    } else if (temp2 != NULL) {
        current->next = temp2;
    }

    // 返回合并后的链表的头节点（跳过dummy节点）
    return dummy->next;
}

// 打印链表
void printList(Node* head) {
    Node* current = head;
    while (current != NULL) {
        printf("%d ", current->data);
        current = current->next;
    }
    printf("\n");
}

// 主函数
int main() {
    // 创建两个升序链表
    Node* list1 = createNode(1);
    list1->next = createNode(3);
    list1->next->next = createNode(5);

    Node* list2 = createNode(2);
    list2->next = createNode(4);
    list2->next->next = createNode(6);

    // 合并两个链表
    Node* mergedList = mergeSortedLists(list1, list2);

    // 打印合并后的链表
    printf("Merged Sorted List: ");
    printList(mergedList);

    // 释放内存
    Node* current = mergedList;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    return 0;
}
```

这个代码定义了两个函数：`mergeSortedLists` 用于合并两个升序链表，`printList` 用于打印链表。`main` 函数创建了两个升序链表，然后调用 `mergeSortedLists` 函数合并它们，最后打印合并后的链表。

