#include <stdlib.h>
#include <time.h>

#define MAX_STATIONS 100

typedef struct {
    int depth;
    int time;
} Station;

int compare(const void *a, const void *b) {
    return ((Station *)a)->time - ((Station *)b)->time;
}

int main() {
    int num_stations, initial_oxygen, final_depth, oxygen_per_depth, oxygen_refill;
    scanf("%d %d %d %d", &num_stations, &initial_oxygen, &final_depth, &oxygen_per_depth);

