        scanf("%d", &station_times[i]);
        stations[i].time = station_times[i];
    }

    // Initialize priority queue
    qsort(stations, num_stations, sizeof(Station), compare);

    int current_oxygen = initial_oxygen;
    int current_depth = 0;
    int total_time = 0;
    int visited[MAX_STATIONS] = {0};

    while (current_depth < final_depth && num_stations > 0) {
