```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_PROCESSES 5
#define MAX_RESOURCE_TYPES 3
#define MAX_RESOURCE_UNITS 10
#define TIME_SLICE 10

typedef struct {
    char name[10];
    int max_resources[MAX_RESOURCE_TYPES];
    int allocated_resources[MAX_RESOURCE_TYPES];
    int state;
} Process;

typedef struct {
    int available_resources[MAX_RESOURCE_TYPES];
    int max_resources[MAX_RESOURCE_TYPES];
    int allocated_resources[MAX_RESOURCE_TYPES];
    int num_processes;
    Process processes[MAX_PROCESSES];
} System;

void initialize_system(System *sys) {
    for (int i = 0; i < MAX_RESOURCE_TYPES; i++) {
        sys->available_resources[i] = MAX_RESOURCE_UNITS;
        sys->max_resources[i] = MAX_RESOURCE_UNITS;
        sys->allocated_resources[i] = 0;
    }
    sys->num_processes = 0;
}

void add_process(System *sys, char *name, int *max_resources) {
    Process *process = &sys->processes[sys->num_processes];
    strcpy(process->name, name);
    for (int i = 0; i < MAX_RESOURCE_TYPES; i++) {
        process->max_resources[i] = max_resources[i];
        process->allocated_resources[i] = 0;
    }
    process->state = 0; // 0: waiting, 1: running, 2: blocked, 3: finished
    sys->num_processes++;
}

int request_resources(System *sys, int *process_id) {
    Process *process = &sys->processes[*process_id];
    for (int i = 0; i < MAX_RESOURCE_TYPES; i++) {
        if (sys->available_resources[i] < process->max_resources[i] - process->allocated_resources[i]) {
            return 0; // Not enough resources
        }
    }
    for (int i = 0; i < MAX_RESOURCE_TYPES; i++) {
        sys->available_resources[i] -= process->max_resources[i] - process->allocated_resources[i];
        process->allocated_resources[i] = process->max_resources[i];
    }
    process->state = 1; // Running
    return 1; // Resources allocated
}

void release_resources(System *sys, int *process_id) {
    Process *process = &sys->processes[*process_id];
    for (int i = 0; i < MAX_RESOURCE_TYPES; i++) {
        sys->available_resources[i] += process->max_resources[i] - process->allocated_resources[i];
        process->allocated_resources[i] = 0;
    }
    process->state = 0; // Waiting
}

void print_system_state(System *sys) {
    printf("Running processes: ");
    for (int i = 0; i < sys->num_processes; i++) {
        if (sys->processes[i].state == 1) {
            printf("%s ", sys->processes[i].name);
        }
    }
    printf("\n");

    printf("Waiting processes: ");
    for (int i = 0; i < sys->num_processes; i++) {
        if (sys->processes[i].state == 0) {
            printf("%s ", sys->processes[i].name);
        }
    }
    printf("\n");

    printf("Blocked processes: ");
    for (int i = 0; i < sys->num_processes; i++) {
        if (sys->processes[i].state == 2) {
