        }
    }
    printf("\n");

    printf("Finished processes: ");
    for (int i = 0; i < sys->num_processes; i++) {
        if (sys->processes[i].state == 3) {
            printf("%s ", sys->processes[i].name);
        }
    }
    printf("\n");
}

void time_slice(System *sys) {
    for (int i = 0; i < sys->num_processes; i++) {
        Process *process = &sys->processes[i];
        if (process->state == 1) {
            int remaining_time = TIME_SLICE;
            while (remaining_time > 0 && request_resources(sys, &i)) {
                remaining_time--;
            }
            if (remaining_time == 0) {
                release_resources(sys, &i);
                process->state = 0; // Waiting
            }
        }
    }
}

int main() {
