    System sys;
    initialize_system(&sys);

    add_process(&sys, "p1", (int[]){2, 3, 1});
    add_process(&sys, "p2", (int[]){1, 2, 2});
    add_process(&sys, "p3", (int[]){3, 1, 1});
    add_process(&sys, "p4", (int[]){2, 2, 1});
    add_process(&sys, "p5", (int[]){1, 1, 1});

    int current_process = 0;
    int time = 0;

    while (current_process < sys.num_processes || time > 0) {
        if (time == 0) {
