typedef struct FunctionNode {
    char name[100];
    struct FunctionNode* next;
} FunctionNode;

typedef struct CallGraph {
    FunctionNode* nodes[MAX_FUNCTIONS];
    int nodeCount;
} CallGraph;

CallGraph* createCallGraph() {
    CallGraph* graph = (CallGraph*)malloc(sizeof(CallGraph));
    graph->nodeCount = 0;
    return graph;
}

FunctionNode* createFunctionNode(const char* name) {
    FunctionNode* node = (FunctionNode*)malloc(sizeof(FunctionNode));
    strcpy(node->name, name);
    node->next = NULL;
    return node;
}

void addFunction(CallGraph* graph, const char* name) {
    if (graph->nodeCount < MAX_FUNCTIONS) {
        if (graph->nodes[graph->nodeCount] == NULL) {
            graph->nodes[graph->nodeCount] = createFunctionNode(name);
        } else {
            FunctionNode* current = graph->nodes[graph->nodeCount];
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = createFunctionNode(name);
        }
        graph->nodeCount++;
    } else {
