        exit(1);
    }
}

void addCall(CallGraph* graph, const char* caller, const char* callee) {
    if (graph->nodeCount < MAX_FUNCTIONS) {
        for (int i = 0; i < graph->nodeCount; i++) {
            if (strcmp(caller, graph->nodes[i]->name) == 0) {
                FunctionNode* current = graph->nodes[i];
                while (current->next != NULL) {
