// Function to check if a number is symmetric
int isSymmetric(int num) {
    int original = num;
    int reversed = 0;
    int temp = num;

    while (temp != 0) {
        int digit = temp % 10;
        reversed = reversed * 10 + digit;
        temp /= 10;
    }

    return original == reversed;
}

// Function to calculate the average of symmetric numbers
double calculateAverage(int n) {
    int sum = 0;
    int count = 0;

    for (int i = 0; i < n; i++) {
        int num;
        scanf("%d", &num);
        if (isSymmetric(num)) {
            sum += num;
            count++;
        }
    }

    if (count == 0) {
        return 0.0;
    }

    return (double)sum / count;
}

