#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

const int MOD = 1000000007;

int countWays(int n, int x, vector<int> &coins) {
    vector<vector<int>> dp(x + 1, vector<int>(n + 1, 0));
    dp[0][0] = 1;

    for (int i = 1; i <= n; ++i) {
        for (int j = coins[i - 1]; j <= x; ++j) {
            dp[j][i] = (dp[j][i - 1] + dp[j - coins[i - 1]][i - 1]) % MOD;
