#include "magazzino.h"

void leggiMagazzino(FILE *file, Magazzino *magazzino) {
    char codice[MAX_CODIGO + 1];
    float costo;
    int quantita;

    fscanf(file, "%s %f %d\n", codice, &costo, &quantita);

    while (fscanf(file, "%s %f %d\n", codice, &costo, &quantita) == 3) {
        strcpy(magazzino->prodotti[magazzino->numProdotti].codice, codice);
        magazzino->prodotti[magazzino->numProdotti].costo = costo;
        magazzino->prodotti[magazzino->numProdotti].quantita = quantita;
        magazzino->numProdotti++;
    }
}

int controllaOperazione(char *codice, int variazione, Magazzino *magazzino) {
    for (int i = 0; i < magazzino->numProdotti; i++) {
        if (strcmp(magazzino->prodotti[i].codice, codice) == 0) {
            if (variazione < 0 && magazzino->prodotti[i].quantita + variazione < 0) {
                return -2; // Decremento più grande della quantità disponibile
            } else if (variazione > 0 && magazzino->prodotti[i].quantita + variazione > MAX_QUANTITA) {
                return -2; // Incremento che supera il limite di 10000
            }
            return 1; // Variazione realizzabile
        }
    }
    return -1; // Prodotto non presente nel magazzino
}

void aggiornaMagazzino(char *codice, int variazione, Magazzino *magazzino, float *totaleCosto) {
    for (int i = 0; i < magazzino->numProdotti; i++) {
        if (strcmp(magazzino->prodotti[i].codice, codice) == 0) {
            magazzino->prodotti[i].quantita += variazione;
            *totaleCosto += magazzino->prodotti[i].costo * variazione;
            return;
        }
    }
}

void stampaMagazzino(Magazzino *magazzino, FILE *file) {
    float totaleCosto = 0.0;

    for (int i = 0; i < magazzino->numProdotti; i++) {
        fprintf(file, "%s: %d x %.2f Euro\n", magazzino->prodotti[i].codice, magazzino->prodotti[i].quantita, magazzino->prodotti[i].costo);
        totaleCosto += magazzino->prodotti[i].costo * magazzino->prodotti[i].quantita;
    }

    fprintf(file, "Totale: %.2f Euro\n", totaleCosto);
}

void ordinaEStampaMagazzino(Magazzino *magazzino, FILE *file) {
    for (int i = 0; i < magazzino->numProdotti - 1; i++) {
        for (int j = i + 1; j < magazzino->numProdotti; j++) {
            if (magazzino->prodotti[i].costo * magazzino->prodotti[i].quantita < magazzino->prodotti[j].costo * magazzino->prodotti[j].quantita) {
                Prodotto temp = magazzino->prodotti[i];
                magazzino->prodotti[i] = magazzino->prodotti[j];
                magazzino->prodotti[j] = temp;
            }
        }
    }

    stampaMagazzino(magazzino, file);
}
