以下是使用C语言实现Dijkstra算法的代码示例：

```c
#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

#define INF INT_MAX

typedef struct {
    int node;
    int distance;
    int previous;
} Edge;

int main() {
    int V, E;
    // 假设 V 是顶点数，E 是边数
    // 这里我们使用一个简单的图作为示例
    V = 5;
    E = 5;

    // 初始化邻接矩阵和距离数组
    int graph[V][V] = {
        {0, 3, INF, 5},
        {3, 0, 2, INF},
        {INF, 2, 0, 1},
        {5, INF, 1, 0},
        {INF, INF, INF, 0}
    };

    int D[V];
    Edge path[V];

    // 初始化
    for (int i = 0; i < V; i++) {
        D[i] = INF;
        path[i].node = -1;
    }
    D[0] = 0; // 起始顶点 V0 的距离为0

    // 标记起始顶点为已访问
    int visited[V] = {0};
    visited[0] = 1;

    // Dijkstra 算法
    while (1) {
        int k;
        // 找到距离最小的未访问顶点
        k = -1;
        for (int i = 0; i < V; i++) {
            if (!visited[i] && (k == -1 || D[i] < D[k])) {
                k = i;
            }
        }

        if (k == -1) break; // 所有顶点都已访问

        // 更新距离和路径
        visited[k] = 1;
        for (int i = 0; i < V; i++) {
            if (graph[k][i] != INF && !visited[i] && (D[k] + graph[k][i] < D[i])) {
                D[i] = D[k] + graph[k][i];
                path[i].node = k;
                path[i].distance = D[i];
            }
        }
    }

    // 打印结果
    printf("Shortest paths from V0:\n");
    for (int i = 1; i < V; i++) {
        printf("To node %d: %d\n", i, D[i]);
    }

    return 0;
}
```

这个代码实现了Dijkstra算法，用于求解图中起始顶点V0到其他顶点的最短路径。它使用邻接矩阵来表示图，并使用一个距离数组D来存储每个顶点的距离。算法会重复地选择距离最小的未访问顶点，更新其距离和路径，直到所有顶点都被访问。

请注意，这个示例代码假设了一个简单的图结构，你可能需要根据你的具体需求调整代码。

