```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/sha.h>
#include <openssl/hmac.h>
#include <openssl/aes.h>

#define KEY_SIZE 32  // AES-128 key size in bytes
#define HMAC_SIZE 64 // HMAC-SHA512 key size in bytes

// Function to derive the AES-128 key using X9.63 KDF
unsigned char* derive_aes_key(unsigned char* salt, unsigned char* info, int salt_len, int info_len) {
    unsigned char* derived_key = (unsigned char*)malloc(KEY_SIZE);
    if (derived_key == NULL) {
        perror("Memory allocation failed");
        exit(1);
    }

    // Initialize the KDF context
    EVP_KDF_CTX* kdf = EVP_KDF_new();
    if (kdf == NULL) {
        perror("KDF context initialization failed");
        free(derived_key);
        return NULL;
    }

    // Set the algorithm and key size
    EVP_KDF_set_algorithm(kdf, EVP_aes_128_cbc());
    EVP_KDF_set_keygen(kdf, EVP_aes_128_cbc());
    EVP_KDF_set_iterations(kdf, 10000); // Number of iterations

    // Set the salt and info
    EVP_KDF_set_salt(kdf, salt, salt_len);
    EVP_KDF_set_key(kdf, info, info_len, EVP_default_keygen_block_size(kdf), derived_key, KEY_SIZE);

    // Derive the key
    if (EVP_KDF_derive(kdf, derived_key, KEY_SIZE) <= 0) {
        perror("KDF derivation failed");
        EVP_KDF_free(kdf);
        free(derived_key);
        return NULL;
    }

    EVP_KDF_free(kdf);
    return derived_key;
}

// Function to derive the HMAC-SHA512 key using X9.63 KDF
unsigned char* derive_hmac_key(unsigned char* salt, unsigned char* info, int salt_len, int info_len) {
    unsigned char* derived_key = (unsigned char*)malloc(HMAC_SIZE);
    if (derived_key == NULL) {
        perror("Memory allocation failed");
        exit(1);
    }

    // Initialize the HMAC context
    HMAC_CTX* hmac = HMAC_CTX_new();
    if (hmac == NULL) {
        perror("HMAC context initialization failed");
        free(derived_key);
        return NULL;
    }

    // Set the algorithm and digest
    HMAC_CTX_set_hash_func(hmac, EVP_sha512());

    // Set the salt and info
    HMAC_Init_ex(hmac, salt, salt_len, EVP_sha512());
    HMAC_Update(hmac, info, info_len);

    // Derive the key
    HMAC_Final(hmac, derived_key, NULL);

    HMAC_CTX_free(hmac);
    return derived_key;
}

int main() {
    // Example salt and info strings
    unsigned char salt[] = "my_salt";
    unsigned char info[] = "my_info";

    // Derive AES-128 key
    unsigned char* aes_key = derive_aes_key(salt, info, sizeof(salt) - 1, sizeof(info) - 1);
    if (aes_key != NULL) {
        printf("AES-128 Key: ");
        for (int i = 0; i < KEY_SIZE; i++) {
            printf("%02x", aes_key[i]);
        }
        printf("\n");
        free(aes_key);
    }

    // Derive HMAC-SHA512 key
    unsigned char* hmac_key = derive_hmac_key(salt, info, sizeof(salt) - 1, sizeof(info) - 1);
    if (hmac_key != NULL) {
        printf("HMAC-SHA512 Key: ");
