// 函数：findLIS
// 描述：找到最长的严格递增子序列
int findLIS(int *nums, int n) {
    // 初始化 dp 数组，所有值都为 1，因为单个元素本身就是递增子序列
    for (int i = 0; i < n; i++) {
        dp[i] = 1;
    }

    // 动态规划部分
    for (int i = 1; i < n; i++) {
        for (int j = 0; j < i; j++) {
            if (nums[i] > nums[j]) {
                dp[i] = dp[i] > dp[j] + 1 ? dp[i] : dp[j] + 1;
            }
        }
    }

    // 找到 dp 数组中的最大值，即最长递增子序列的长度
    int maxLength = 0;
    for (int i = 0; i < n; i++) {
        maxLength = dp[i] > maxLength ? dp[i] : maxLength;
    }

    return maxLength;
}

// 函数：printLIS
// 描述：打印最长的严格递增子序列
void printLIS(int *nums, int n, int maxLength) {
    int *sequence = (int *)malloc(maxLength * sizeof(int));
    int index = 0;
    int *dp = dp;

    for (int i = 0; i < n; i++) {
        if (dp[i] == maxLength) {
            sequence[index++] = nums[i];
            // 更新 dp 数组，消除当前元素
            for (int j = i; j < n; j++) {
                if (dp[j] == dp[i] - 1) {
                    dp[j] = 1;
                }
            }
        }
    }

    printf("最长的严格递增子序列: ");
    for (int i = 0; i < index; i++) {
        printf("%d ", sequence[i]);
    }
    printf("\n");

    free(sequence);
}

int main() {
    int nums[] = {10, 9, 2, 5, 3, 7, 101, 18};
    int n = sizeof(nums) / sizeof(nums[0]);

    int maxLength = findLIS(nums, n);
    printLIS(nums, n, maxLength);

    return 0;
}
```

### 解释

1. **初始化**：我们首先初始化 `dp` 数组，其中 `dp[i]` 表示长度为 `i` 的最长递增子序列的长度。所有元素都初始化为 1，因为单个元素本身就是递增子序列。

2. **动态规划**：对于每个元素 `nums[i]`，我们检查从 `0` 到 `i-1` 之间的所有元素 `nums[j]`，如果 `nums[i] > nums[j]`，则更新 `dp[i]` 为 `dp[i]` 和 `dp[j] + 1` 之间的最大值。

3. **找到最长递增子序列**：遍历 `dp` 数组，找到最大值，即最长递增子序列的长度。

4. **打印结果**：使用动态规划数组 `dp` 回溯找到最长的递增子序列，并打印出来。

这个方法的时间复杂度是 O(n^2)，其中 n 是数组的长度。空间复杂度是 O(n)，因为我们使用了 `dp` 数组。

