const int MAX_OFFICES = 100000;
const int MAX_CONNECTIONS = 1000000;
const int INF = numeric_limits<int>::max();

struct Edge {
    int to, latency;
};

vector<Edge> graph[MAX_OFFICES];
int latency[MAX_OFFICES];
int shortestPath[MAX_OFFICES];
bool visited[MAX_OFFICES];

void initialize(int n, int m, int k) {
    for (int i = 0; i < MAX_OFFICES; i++) {
        graph[i].clear();
        visited[i] = false;
        shortestPath[i] = INF;
    }
}

void addConnection(int a, int b, int l, int type) {
    if (type == 1) {
        graph[a].push_back({b, l});
        graph[b].push_back({a, l});
    } else {
        graph[a].push_back({b, l});
        graph[b].push_back({a, l});
    }
}

void dijkstra(int start) {
    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;
    pq.push({0, start});
    shortestPath[start] = 0;

    while (!pq.empty()) {
        int u = pq.top().second;
        pq.pop();

        if (visited[u]) continue;
        visited[u] = true;

        for (const Edge& edge : graph[u]) {
            int v = edge.to;
            int newLatency = shortestPath[u] + edge.latency;

            if (newLatency < shortestPath[v]) {
                shortestPath[v] = newLatency;
                pq.push({newLatency, v});
            }
        }
    }
}

int solve(int n, int m, int k) {
    int maxFiberConnections = 0;

    for (int i = 0; i < k; i++) {
        int u = 1; // HQ
        int v = i + 2; // Office connected by fiber

        dijkstra(u);

        int minLatency = INF;
        for (int j = 0; j < n; j++) {
            if (shortestPath[j] < minLatency) {
                minLatency = shortestPath[j];
            }
        }

        if (minLatency == INF) {
            break;
        }

        int removedFiber = 0;
        for (int j = 0; j < k; j++) {
            if (j != i) {
                int u2 = j + 2; // Office connected by fiber to remove
                dijkstra(u2);

                if (shortestPath[1] == minLatency) {
                    removedFiber++;
                }
            }
        }

        maxFiberConnections = max(maxFiberConnections, removedFiber);
    }

    return maxFiberConnections;
}

int main() {
    int n, m, k;
    cin >> n >> m >> k;

    initialize(n, m, k);

    for (int i = 0; i < m; i++) {
        int a, b, l;
        cin >> a >> b >> l;
        addConnection(a, b, l, 1);
    }

    for (int i = 0; i < k; i++) {
        int a, b, l;
        cin >> a >> b >> l;
        addConnection(1, b, l, 2);
    }

    int result = solve(n, m, k);
    cout << result << endl;

    return 0;
}
```

This code defines a graph data structure and uses Dijkstra's algorithm to find the shortest path between the HQ (office 1) and other offices. It then iterates through the fiber connections and checks if removing them maintains the same shortest path latency. The maximum number of fiber connections that can be removed is calculated and printed.

