```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define BMP_FILE_HEADER_SIZE 14
#define DIB_HEADER_SIZE 40
#define COLOR_TABLE_ENTRY_SIZE 4

typedef struct {
    unsigned short type;
    unsigned int size;
    unsigned short reserved1;
    unsigned short reserved2;
    unsigned int offset;
} BMPFileHeader;

typedef struct {
    unsigned int size;
    unsigned short reserved1;
    unsigned short reserved2;
    unsigned short planes;
    unsigned short bitsPerPixel;
    unsigned int compression;
    unsigned int imageSize;
    int xPixelsPerMeter;
    int yPixelsPerMeter;
    unsigned int colorsUsed;
    unsigned int importantColors;
} BMBDIBHeader;

typedef struct {
    unsigned char blue;
    unsigned char green;
    unsigned char red;
} COLORTABLEENTRY;

void writeBMPFileHeader(FILE *fp, unsigned int fileSize) {
    BMPFileHeader header;
    header.type = 0x4D42; // 'BM'
    header.size = fileSize;
    header.reserved1 = 0;
    header.reserved2 = 0;
    header.offset = 54; // 54 is the size of the file header and DIB header

    fwrite(&header, sizeof(header), 1, fp);
}

void writeBMBDIBHeader(FILE *fp, int width, int height, int bytesPerPixel, int sizeOfImage) {
    BMBDIBHeader header;
    header.size = 40;
    header.reserved1 = 0;
    header.reserved2 = 0;
    header.planes = 1;
    header.bitsPerPixel = 24; // 24 bits per pixel
    header.compression = 0; // no compression
    header.imageSize = sizeOfImage;
    header.xPixelsPerMeter = 0;
    header.yPixelsPerMeter = 0;
    header.colorsUsed = 0;
    header.importantColors = 0;

    fwrite(&header, sizeof(header), 1, fp);
}

void writeCOLORTABLE(FILE *fp, int colors, COLORTABLEENTRY *colorTable) {
    fwrite(colorTable, colors * COLOR_TABLE_ENTRY_SIZE, 1, fp);
}

void writeImage(FILE *fp, int width, int height, unsigned char *imageData) {
    for (int y = height - 1; y >= 0; --y) {
        for (int x = 0; x < width; ++x) {
            int index = (y * width + x) * 3;
            fwrite(&imageData[index], 1, 1, fp);
            fwrite(&imageData[index + 1], 1, 1, fp);
            fwrite(&imageData[index + 2], 1, 1, fp);
        }
    }
}

void writeBMP(const char *filename, int width, int height, unsigned char *imageData) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("fopen");
        exit(1);
    }

    writeBMPFileHeader(fp, BMP_FILE_HEADER_SIZE + DIB_HEADER_SIZE + width * height * 3);
    writeBMBDIBHeader(fp, width, height, 3, width * height * 3);
    writeCOLORTABLE(fp, 256, (COLORTABLEENTRY *)malloc(256 * 3)); // allocate and initialize color table
    writeImage(fp, width, height, imageData);

    fclose(fp);
}

