    int height = 480;
    int bytesPerPixel = 3;
    int sizeOfImage = width * height * bytesPerPixel;
    unsigned char *imageData = (unsigned char *)malloc(sizeOfImage);
    // Initialize image data here

    writeBMP("output.bmp", width, height, imageData);

    free(imageData);
    return 0;
}
