```c
#include <stdio.h>
#include <stack>
#include <iostream>

using namespace std;

// 定义操作符优先级
enum OperatorPriority {
    ADD = 1,
    SUB,
    MUL,
    DIV,
    MOD,
    LPAREN,
    RPAREN
};

// 函数来确定操作符的优先级
int getPrecedence(char op) {
    switch (op) {
        case '+': case '-': return OperatorPriority::ADD;
        case '*': case '/': case '%': return OperatorPriority::MUL;
        case '(': return OperatorPriority::LPAREN;
        case ')': return OperatorPriority::RPAREN;
        default: return 0; // 忽略其他字符
    }
}

// 函数来确定最后一个被运算的操作符
char getLastOperator(const string& expression) {
    stack<char> operatorStack;
    string result;

    for (char c : expression) {
        if (isdigit(c) || c == '.') {
            result += c;
        } else if (c == '(') {
            operatorStack.push(c);
        } else if (c == ')') {
            while (operatorStack.top() != '(') {
                result += operatorStack.top();
                operatorStack.pop();
            }
            operatorStack.pop(); // 弹出 '('
        } else if (isspace(c)) {
            continue; // 忽略空格
        } else {
            while (!operatorStack.empty() && getPrecedence(operatorStack.top()) >= getPrecedence(c)) {
                result += operatorStack.top();
                operatorStack.pop();
            }
            operatorStack.push(c);
        }
    }

    while (!operatorStack.empty()) {
        result += operatorStack.top();
        operatorStack.pop();
    }

    // 查找最后一个操作符
    for (int i = result.size() - 1; i >= 0; --i) {
        if (getPrecedence(result[i]) > 0) {
            return result[i];
        }
    }

    return 0; // 如果没有操作符，返回0
}

int main() {
    string expression;
    cout << "Enter an expression: ";
    cin >> expression;

    char lastOperator = getLastOperator(expression);
    cout << "The last operator is: " << lastOperator << endl;

    return 0;
}
```

这个程序使用了一个栈来跟踪操作符的顺序，并使用递归来确定操作符的优先级。它还忽略了空格和其他非操作符字符。最后，它返回表达式中最后一个被运算的操作符。

