### Klient (client.c)

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>

#define PORT 4001  // Port do komunikacji
#define BUFFER_SIZE 1024

int main() {
    int sockfd;
    struct sockaddr_in server_addr;
    char buffer[BUFFER_SIZE];
    char name[100];

    // Wczytanie imienia i nazwiska z konsoli
    printf("Wpisz swoje imie i nazwisko: ");
    fgets(name, sizeof(name), stdin);
    name[strcspn(name, "\n")] = 0;  // Usunięcie znaka nowelizacji

    // Tworzenie socketu
    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }

    // Konfiguracja adresu serwera
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(PORT);
    server_addr.sin_addr.s_addr = INADDR_ANY;

    // Wysłanie datagramu do serwera
    if (sendto(sockfd, name, strlen(name), 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Send failed");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    // Oczekiwanie na odpowiedź serwera
    int bytes_received = recvfrom(sockfd, buffer, BUFFER_SIZE, 0, NULL, NULL);
    if (bytes_received < 0) {
        perror("Receive failed");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    // Wyświetlenie odpowiedzi serwera
    printf("Odpowiedź serwera: %s\n", buffer);

    // Zamknięcie socketu
    close(sockfd);

    return 0;
}
```

### Serwer (server.c)

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>

#define PORT 4001  // Port do komunikacji
#define BUFFER_SIZE 1024

int main() {
    int sockfd;
    struct sockaddr_in server_addr, client_addr;
    socklen_t addr_len = sizeof(client_addr);
    char buffer[BUFFER_SIZE];

    // Tworzenie socketu
    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }

    // Konfiguracja adresu serwera
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(PORT);
    server_addr.sin_addr.s_addr = inet_addr("127.0.0.1");  // Adres IP serwera (127.0.0.1 dla lokalnego testu)

    // Zapisanie adresu serwera do socketu
    if (bind(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Bind failed");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    printf("Serwer czeka na połączenia...\n");

    // Pętla nieskończona do obsługi klientów
    while (1) {
        // Oczekiwanie na przychodzący datagram
        int bytes_received = recvfrom(sockfd, buffer, BUFFER_SIZE, 0, (struct sockaddr *)&client_addr, &addr_len);
        if (bytes_received < 0) {
            perror("Receive failed");
            continue;
        }

        // Konwersja adresu IP klienta do humanitarnego formatu
        char client_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_addr.sin_addr, client_ip, INET_ADDRSTRLEN);

        // Wyświetlenie informacji o klientie
        printf("Otrzymałem od %s: %s\n", client_ip, buffer);

        // Odpowiedź do klienta
        char response[BUFFER_SIZE];
        snprintf(response, BUFFER_SIZE, "ODPOWIEDZ: %s", buffer);
        sendto(sockfd, response, strlen(response), 0, (struct sockaddr *)&client_addr, addr_len);
    }

    // Zamknięcie socketu
    close(sockfd);

    return 0;
}
```

### Kompilacja i Uruchomienie

1. **Kompilacja**:
