#define BUFFER_SIZE 1024

int main() {
    int sockfd;
    struct sockaddr_in server_addr;
    char buffer[BUFFER_SIZE];
    char name[100];

    // Otwieranie gniazda
    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("Błąd przy tworzeniu gniazda");
        exit(1);
    }

    // Przygotowanie adresu serwera
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(PORT);
    server_addr.sin_addr.s_addr = INADDR_ANY;

    // Załączenie gniazda do adresu serwera
    if (bind(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Błąd przy przypięciu gniazda");
        close(sockfd);
        exit(1);
    }

    // Przygotowanie imienia i nazwiska
    printf("Wpisz swoje imie i nazwisko: ");
    fgets(name, sizeof(name), stdin);
    name[strcspn(name, "\n")] = 0; // Usunięcie znaku nowelowego

