        printf("%s", buffer);
        memset(buffer, 0, BUFFER_SIZE); // Czyszczenie bufora
    }

    if (bytes_read < 0) {
        perror("Błąd przy odbiorze danych");
    }

    close(sockfd);
    return 0;
}
