### Kod Serwera

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>

#define PORT 8080
#define BUFFER_SIZE 1024

int main() {
    int sockfd, clientfd;
    struct sockaddr_in server_addr, client_addr;
    socklen_t addr_len = sizeof(client_addr);
    char buffer[BUFFER_SIZE];
    char name[100];

    // Otwieranie gniazda
    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("Błąd przy tworzeniu gniazda");
        exit(1);
    }

    // Przygotowanie adresu serwera
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(PORT);
    server_addr.sin_addr.s_addr = INADDR_ANY;

    // Załączenie gniazda do adresu serwera
    if (bind(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Błąd przy przypięciu gniazda");
        close(sockfd);
        exit(1);
    }

    // Akceptowanie połączeń od klientów
    if (listen(sockfd, 5) < 0) {
        perror("Błąd przy akceptowaniu połączeń");
        close(sockfd);
        exit(1);
    }

    printf("Oczekiwanie na połączenia...\n");

    // Akceptowanie połączenia od klienta
    clientfd = accept(sockfd, (struct sockaddr *)&client_addr, &addr_len);
    if (clientfd < 0) {
        perror("Błąd przy akceptowaniu połączenia");
        close(sockfd);
        exit(1);
    }

    // Odbieranie imienia i nazwiska od klienta
    int bytes_read = read(clientfd, name, sizeof(name));
    if (bytes_read < 0) {
        perror("Błąd przy odbiorze danych");
        close(clientfd);
        close(sockfd);
        exit(1);
    }
    name[bytes_read] = 0; // Zakończenie stringa

    // Odpowiedź w wielkich literach
    printf("Odbrano: %s\n", name);
    strupr(name); // Konwertowanie do wielkich liter
    send(clientfd, name, strlen(name), 0);

    // Zamykanie gniazda
    close(clientfd);
    close(sockfd);
    return 0;
}
```

