在用户空间，我们可以使用`mmap`来映射内核空间的文件，并通过这个映射来读写数据。

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <unistd.h>

#define DEVICE_NAME "/dev/my_device"
#define BUFFER_SIZE 1024

int main() {
    int fd;
    void *mapped_ptr;
    char buffer[BUFFER_SIZE];

    // Open the device file
    fd = open(DEVICE_NAME, O_RDWR);
    if (fd == -1) {
        perror("Failed to open device");
        exit(1);
    }

    // Map the device file into memory
    mapped_ptr = mmap(NULL, BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (mapped_ptr == MAP_FAILED) {
        perror("Failed to mmap device");
        close(fd);
        exit(1);
    }

    // Write to the mapped region
    strcpy(mapped_ptr, "Hello from user space!");

    // Read from the mapped region
    memset(buffer, 0, BUFFER_SIZE);
    read(fd, buffer, BUFFER_SIZE);
    printf("Message from kernel: %s\n", buffer);

    // Unmap the memory
    if (munmap(mapped_ptr, BUFFER_SIZE) == -1) {
        perror("Failed to munmap device");
    }

    // Close the device file
    close(fd);

    return 0;
}
```

### 编译和运行

1. **编译内核模块**：
