```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/select.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <errno.h>

#define PORT 8080
#define BACKLOG 10

void handle_client(int client_socket) {
    char buffer[1024];
    int bytes_read;

    while ((bytes_read = read(client_socket, buffer, sizeof(buffer))) > 0) {
        buffer[bytes_read] = '\0';
        printf("Received from client: %s\n", buffer);

        // Обработка полученной информации (например, отправка ответа)
        char response[1024];
        snprintf(response, sizeof(response), "Server received: %s", buffer);
        write(client_socket, response, strlen(response));
    }

    if (bytes_read < 0) {
        perror("Error reading from client");
    }

    close(client_socket);
}

int main() {
    int server_socket, new_socket;
    struct sockaddr_in server_addr, client_addr;
    socklen_t sin_size;
    fd_set read_fds;

    // Создание и настройка сервера
    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket < 0) {
        perror("Error creating socket");
        exit(1);
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    if (bind(server_socket, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Error binding socket");
        close(server_socket);
        exit(1);
    }

    if (listen(server_socket, BACKLOG) < 0) {
        perror("Error listening on socket");
        close(server_socket);
        exit(1);
    }

    FD_ZERO(&read_fds);
    FD_SET(server_socket, &read_fds);

    while (1) {
        // Ожидание ввода/вывода на готовых дескрипторах
        sin_size = sizeof(client_addr);
        int max_fd = server_socket;
        int activity;

        activity = select(max_fd + 1, &read_fds, NULL, NULL, NULL);
        if (activity < 0) {
            perror("Error in select");
            exit(1);
        }

        if (FD_ISSET(server_socket, &read_fds)) {
            // Прибытие нового клиента
            new_socket = accept(server_socket, (struct sockaddr *)&client_addr, &sin_size);
            if (new_socket < 0) {
                perror("Error accepting connection");
                continue;
            }

            FD_SET(new_socket, &read_fds);
            if (new_socket > max_fd) {
                max_fd = new_socket;
            }

            printf("New client connected\n");
        }

        for (int i = 0; i <= max_fd; i++) {
            if (FD_ISSET(i, &read_fds)) {
                if (i == server_socket) {
                    // Прибытие нового клиента
                    continue;
                }

                handle_client(i);
                break; // Обработка одного клиента в одном потоке
            }
        }
    }

    close(server_socket);
    return 0;
}
```

В этом примере кода сервер создает socket, bindит его к адресу и порту, и слушает вхожденные соединения. Используя системный вызов `select`, сервер ожидает ввода/вывода на готовых дескрипторах. Когда arrives новый клиент, он добавляется в `fd_set` и ожидается в `select`. Когда клиент готов для обработки, сервер вызывает функцию `handle_client`, которая обрабатывает вхожденные данные и отправляет ответ.

Обратите внимание, что этот пример демонстрирует псевдопараллельную работу клиентов, поскольку каждый клиент обрабатывается в одном потоке. В реальных сценариях для обеспечения истинной параллельности можно использовать многопотоковые или многовспомогательные подходы.

