    printf("%04d-%02d-%02d\n", date.year, date.month, date.day);
}

// 调整日期
void adjustDate(Date *date, int yearChange, int monthChange, int dayChange) {
    date->year += yearChange;
    date->month += monthChange;
    date->day += dayChange;

    // 处理月份和日期的溢出
    if (date->month > 12) {
        date->year += date->month / 12;
        date->month %= 12;
    } else if (date->month < 1) {
        date->year -= (1 - date->month) / 12;
        date->month += 12;
    }

    if (date->day > daysInMonth(date->year, date->month)) {
        date->month += 1;
        if (date->month > 12) {
            date->year += 1;
            date->month -= 12;
        }
        date->day = 1;
    } else if (date->day < 1) {
        date->month -= 1;
        if (date->month < 1) {
            date->year -= 1;
            date->month += 12;
        }
        date->day = daysInMonth(date->year, date->month);
    }
}

// 获取月份的天数
int daysInMonth(int year, int month) {
    if (month == 2) {
        if ((year % 4 == 0 && year % 100 != 0) || year % 400 == 0) {
            return 29;
        } else {
            return 28;
        }
    } else if (month == 4 || month == 6 || month == 9 || month == 11) {
        return 30;
    } else {
        return 31;
    }
}

// 重置日期
void resetDate(Date *date) {
    time_t t = time(NULL);
    struct tm *now = localtime(&t);
