```c
#include <stdio.h>
#include <stdlib.h>

struct studinfo {
    int stnr;
    char name[10];
    int grade;
};

// Binary search function to find a student's information
int binarySearch(struct studinfo arr[], int low, int high, int stnr) {
    int mid;

    if (low <= high) {
        mid = (low + high) / 2;

        if (arr[mid].stnr == stnr) {
            return mid; // Found the student
        } else if (arr[mid].stnr < stnr) {
            return binarySearch(arr, mid + 1, high, stnr); // Search in the right half
        } else {
            return binarySearch(arr, low, mid - 1, stnr); // Search in the left half
        }
    }

    return -1; // Student not found
}

void main() {
    struct studinfo s[10];
    int cnt = 0;
    FILE *stud_file;
    int stnr;

    // Read data from the file
    stud_file = fopen("C:\\cmpe231\\2009Spring\\student.txt", "r");
    while (!feof(stud_file)) {
        fscanf(stud_file, "%d %s %d", &s[cnt].stnr, s[cnt].name, &s[cnt].grade);
        cnt++;
    }
    fclose(stud_file);

    // Example usage of binary search
    printf("Enter student number: ");
    scanf("%d", &stnr);

    int position = binarySearch(s, 0, cnt - 1, stnr);

    if (position != -1) {
        printf("Student found:\n");
        printf("Student Number: %d\n", s[position].stnr);
        printf("Name: %s\n", s[position].name);
        printf("Grade: %d\n", s[position].grade);
        printf("Position in array: %d\n", position);
    } else {
        printf("Student not found.\n");
    }
}
```

