import org.yaml.snakeyaml.Yaml;
import org.yaml.snakeyaml.constructor.Constructor;
import org.yaml.snakeyaml.representer.Representer;

import java.util.Map;

public class ConfigConverter {

    public static String convertYamlToString(String yamlString) {
        Yaml yaml = new Yaml();
        return yaml.dump(yaml.load(yamlString));
    }

    public static String convertStringToYaml(Map<String, Object> config) {
        Representer representer = new Representer(new Constructor());
        return new Yaml(representer).dump(config);
    }
}
```

