import java.io.*;
import java.util.Date;

public class ChatRecord {
    private String sender;
    private String message;
    private Date timestamp;

    public ChatRecord(String sender, String message) {
        this.sender = sender;
        this.message = message;
        this.timestamp = new Date();
    }

    public String getSender() {
        return sender;
    }

    public String getMessage() {
        return message;
    }

    public Date getTimestamp() {
        return timestamp;
    }

    public void saveToFile(String filePath) throws IOException {
        try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream(filePath, true))) {
            oos.writeObject(this);
        }
    }

    public static ChatRecord loadFromRecordFile(String filePath) throws IOException, ClassNotFoundException {
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filePath))) {
            return (ChatRecord) ois.readObject();
        }
    }
}
```

