import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.Random;

public class WordSelector {

    public static void main(String[] args) {
        String filePath = "path/to/your/textfile.txt"; // Replace with your file path
        int numWordsToSelect = 10;

        try (BufferedReader reader = new BufferedReader(new FileReader(filePath))) {
            String line;
            int wordCount = 0;

            // Count the number of words in the file
            while ((line = reader.readLine()) != null) {
                String[] words = line.split("\\s+");
                wordCount += words.length;
            }

            // Reset the reader to read the entire file again
            reader.close();
            reader.reset();

            String[] allWords = new String[wordCount];
            int index = 0;

            // Read the file line by line and store words in an array
            while ((line = reader.readLine()) != null) {
                String[] words = line.split("\\s+");
                for (String word : words) {
                    allWords[index++] = word;
                }
            }

            // Create a Random object
            Random random = new Random();

            // Select random words
            String[] selectedWords = new String[numWordsToSelect];
            for (int i = 0; i < numWordsToSelect; i++) {
                int randomIndex = random.nextInt(allWords.length);
                selectedWords[i] = allWords[randomIndex];
                // Remove the selected word from the array to avoid duplicates
                for (int j = randomIndex; j < allWords.length - 1; j++) {
                    allWords[j] = allWords[j + 1];
                }
                allWords = Arrays.copyOf(allWords, allWords.length - 1);
            }

            // Print the selected words
            for (String word : selectedWords) {
                System.out.println(word);
            }

        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
