### Step 1: Create the `NetworkConnection` Class

```java
import android.os.AsyncTask;
import android.util.Log;
import java.io.IOException;
import java.net.Socket;
import java.net.UnknownHostException;

public class NetworkConnection {
    private static final String TAG = "NetworkConnection";
    private Socket socket;
    private OnConnectionListener listener;

    public interface OnConnectionListener {
        void onConnected(Socket socket);
        void onConnectionFailed(String message);
    }

    public NetworkConnection(OnConnectionListener listener) {
        this.listener = listener;
    }

    public void connect(String host, int port) {
        new ConnectTask(host, port).execute();
    }

    private class ConnectTask extends AsyncTask<Void, Void, Socket> {
        private String host;
        private int port;

        public ConnectTask(String host, int port) {
            this.host = host;
            this.port = port;
        }

        @Override
        protected Socket doInBackground(Void... voids) {
            try {
                socket = new Socket(host, port);
                Log.i(TAG, "Connected to " + host + " on port " + port);
                return socket;
            } catch (UnknownHostException e) {
                Log.e(TAG, "UnknownHostException: " + e.getMessage());
                return null;
            } catch (IOException e) {
                Log.e(TAG, "IOException: " + e.getMessage());
                return null;
            }
        }

        @Override
        protected void onPostExecute(Socket socket) {
            if (socket != null) {
                if (listener != null) {
                    listener.onConnected(socket);
                }
            } else {
                if (listener != null) {
                    listener.onConnectionFailed("Failed to connect to the server.");
                }
            }
        }
    }

    public void close() {
        if (socket != null) {
            try {
                socket.close();
                socket = null;
            } catch (IOException e) {
                Log.e(TAG, "Error closing socket: " + e.getMessage());
            }
        }
    }
}
```

### Step 2: Use the `NetworkConnection` Class in Your Main Activity

Here's an example of how you can use the `NetworkConnection` class in your main activity:

```java
import android.os.Bundle;
import android.util.Log;
import androidx.appcompat.app.AppCompatActivity;
import java.net.Socket;

public class MainActivity extends AppCompatActivity {
    private NetworkConnection networkConnection;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        networkConnection = new NetworkConnection(new NetworkConnection.OnConnectionListener() {
            @Override
            public void onConnected(Socket socket) {
                Log.i("MainActivity", "Connected to server");
                // Handle the connected socket here
            }

            @Override
            public void onConnectionFailed(String message) {
                Log.e("MainActivity", "Connection failed: " + message);
            }
        });
    }

    @Override
    protected void onDestroy() {
        super.onDestroy();
        if (networkConnection != null) {
            networkConnection.close();
        }
    }

    public void connectToServer() {
        networkConnection.connect("example.com", 8080);
    }
}
```

### Step 3: Create the Layout (if needed)

You can create a simple layout for your activity if needed. For this example, I'll keep it simple and just use the default layout.

### Step 4: Run the App

You can now run your Android app, and when you start it, it will attempt to connect to the specified host and port in a separate thread. If the connection is successful, it will call the `onConnected` method of the `OnConnectionListener` interface. If the connection fails, it will call the `onConnectionFailed` method.

Make sure to handle the `onDestroy` method to close the socket when the activity is destroyed to avoid resource leaks.

