```pseint
// Definir la estructura del registro
STRUCT Registro {
    DNI: STRING;
    Nombre: STRING;
    Apellido: STRING;
    Telefono: STRING;
}

// Función para leer el archivo y cargar los registros en una lista
FUNCTION CargarRegistros(ARCHIVO: STRING): LIST[Registro] {
    var registros: LIST[Registro]
    var linea: STRING
    var registro: Registro

    OPEN ARCHIVO FOR INPUT TO linea
    WHILE NOT EOF(ARCHIVO) {
        READ linea
        Split(linea, ',', registro)
        ADD registro TO registros
    }
    CLOSE ARCHIVO

    RETURN registros
}

// Función para buscar un registro por DNI
FUNCTION BuscarRegistro(registros: LIST[Registro], DNI: STRING): Registro {
    var registro: Registro
    FOR EACH registro IN registros {
        IF registro.DNI = DNI {
            RETURN registro
        }
    }
    RETURN NULL
}

// Función principal para realizar la consulta
FUNCTION ConsultarRegistro(archivo: STRING, DNI: STRING): STRING {
    var registros: LIST[Registro]
    var registro: Registro
    var resultado: STRING

    // Cargar los registros del archivo
    registros = CargarRegistros(archivo)

    // Buscar el registro por DNI
    registro = BuscarRegistro(registros, DNI)

    // Verificar si se encontró el registro
    IF registro IS NOT NULL {
        resultado = "Registro encontrado:\n"
        resultado += "DNI: " + registro.DNI + "\n"
        resultado += "Nombre: " + registro.Nombre + "\n"
        resultado += "Apellido: " + registro.Apellido + "\n"
        resultado += "Teléfono: " + registro.Telefono
    } ELSE {
        resultado = "ERROR: No se encontró el registro con el DNI " + DNI
    }

    RETURN resultado
}

// Ejemplo de uso
MAIN {
    var archivo: STRING = "DIRECTORIO.txt"
    var DNI: STRING = "12345678A"

    PRINT ConsultarRegistro(archivo, DNI)
}
```

### Explicación del código:

1. **Estructura del Registro**: Se define una estructura `Registro` que contiene los campos `DNI`, `Nombre`, `Apellido` y `Telefono`.

2. **Cargar Registros**: Esta función lee el archivo `DIRECTORIO.txt` y carga los registros en una lista de tipo `Registro`. Los datos se leen línea por línea y se separan por comas para crear un objeto `Registro`.

3. **Buscar Registro**: Esta función busca un registro en la lista de registros por el número del DNI proporcionado. Devuelve el registro encontrado o `NULL` si no se encuentra.

4. **Consultar Registro**: Esta función es la principal que realiza la consulta. Llama a `CargarRegistros` para cargar los datos del archivo, luego a `BuscarRegistro` para buscar el registro por DNI, y finalmente imprime el resultado. Si no se encuentra el registro, emite un mensaje de error.

