接下来，我们将编写一个简单的Java程序，该程序使用Socket接收H.264流数据，并使用OpenCV将其显示在窗口中。

```java
import org.opencv.core.Core;
import org.opencv.core.Mat;
import org.opencv.imgcodecs.Imgcodecs;
import org.opencv.imgproc.Imgproc;
import org.opencv.videoio.VideoCapture;
import org.opencv.videoio.VideoWriter;
import org.opencv.videoio.Videoio;

import java.awt.image.BufferedImage;
import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.net.Socket;
import javax.imageio.ImageIO;

public class H264StreamReceiver {

    public static void main(String[] args) throws IOException {
        // 创建Socket连接
        Socket socket = new Socket("127.0.0.1", 12345);
        FileInputStream fis = new FileInputStream(new File("output.h264"));

        // 创建VideoCapture对象
        VideoCapture capture = new VideoCapture(0); // 0表示默认摄像头

        // 创建Mat对象用于存储图像
        Mat frame = new Mat();

        // 创建VideoWriter对象用于保存解码后的帧
        VideoWriter writer = new VideoWriter("output.avi", Imgcodecs.IMAGESIZE_ANY, 25.0, new Size(640, 480), true);

        while (true) {
            // 从Socket接收数据
            byte[] buffer = new byte[1024];
            int bytesRead = fis.read(buffer);
            if (bytesRead > 0) {
                socket.getOutputStream().write(buffer, 0, bytesRead);
            }

            // 从摄像头读取帧
            if (capture.read(frame)) {
                // 解码H.264帧（这里假设你已经有了一个H.264解码器）
                // 这里我们直接使用OpenCV的Mat对象，假设帧已经解码为YUV格式
                // 你需要根据实际情况调整帧的格式和尺寸

                // 将帧转换为OpenCV的Mat对象
                BufferedImage image = new BufferedImage(frame.width(), frame.height(), BufferedImage.TYPE_INT_RGB);
                for (int y = 0; y < frame.rows(); y++) {
                    for (int x = 0; x < frame.cols(); x++) {
                        int pixel = frame.get(y, x).toInt();
                        int r = (pixel >> 16) & 0xFF;
                        int g = (pixel >> 8) & 0xFF;
                        int b = pixel & 0xFF;
                        image.setRGB(x, y, (r << 16) | (g << 8) | b);
                    }
                }

                // 显示帧
                Imgproc.imshow("H.264 Stream", image);

                // 保存帧（可选）
                writer.write(image);

                // 按'q'键退出
                if (Imgproc.waitKey(1) == 'q') {
                    break;
                }
            }
        }

        // 释放资源
        capture.release();
        writer.release();
        socket.close();
        fis.close();
    }
