```java
import io.netty.buffer.ByteBuf;
import io.netty.buffer.Unpooled;
import io.netty.channel.Channel;
import io.netty.channel.ChannelHandlerContext;
import io.netty.channel.SimpleChannelInboundHandler;
import io.netty.channel.socket.SocketChannel;
import io.netty.handler.codec.http.*;
import io.netty.util.CharsetUtil;
import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

public class ImageServerHandler extends SimpleChannelInboundHandler<FullHttpRequest> {

    private static final String INDEX_PAGE = "/index.html";
    private static final String UPLOAD_PAGE = "/upload.html";
    private static final String UPLOAD_PATH = "uploads/";

    @Override
    protected void channelRead0(ChannelHandlerContext ctx, FullHttpRequest req) throws Exception {
        if (req.method() != HttpMethod.POST) {
            sendResponse(ctx, "Method not allowed", 405);
            return;
        }

        if (!req.uri().equals(UPLOAD_PAGE)) {
            sendResponse(ctx, "Invalid request URI", 400);
            return;
        }

        // 处理文件上传
        handleFileUpload(ctx, req);
    }

    private void handleFileUpload(ChannelHandlerContext ctx, FullHttpRequest req) throws Exception {
        // 获取请求的文件
        HttpHeaders headers = req.headers();
        String fileName = headers.get(HttpHeaderNames.CONTENT_DISPOSITION).split(";")[1].trim().replaceAll("\"", "");

        // 创建文件保存路径
        Path filePath = Paths.get(UPLOAD_PATH, fileName);
        File file = filePath.toFile();

        // 写入文件
        try (FileOutputStream fos = new FileOutputStream(file)) {
            ByteBuf buffer = req.content();
            while (buffer.isReadable()) {
                fos.write(buffer.readBytes(buffer.readableBytes()));
            }
        }

        // 发送响应
        sendResponse(ctx, "File uploaded successfully", 200);
    }

    private void sendResponse(ChannelHandlerContext ctx, String message, int statusCode) {
        FullHttpResponse response = new FullHttpResponse(HttpVersion.HTTP_1_1, HttpResponseStatus.fromCode(statusCode), Unpooled.wrappedBuffer(message.getBytes(CharsetUtil.UTF_8)));
        response.headers().set(HttpHeaderNames.CONTENT_TYPE, "text/plain");
        ctx.channel().writeAndFlush(response);
    }

    @Override
    public void exceptionCaught(ChannelHandlerContext ctx, Throwable cause) throws Exception {
        cause.printStackTrace();
        ctx.close();
    }
}

public class ImageServer {
    public static void main(String[] args) throws Exception {
        // 创建Netty事件循环组
        io.netty.event.EventLoopGroup group = new io.netty.util.concurrent.EventExecutorGroup();
        try {
            // 创建Netty服务器通道
            io.netty.channel.Channel ch = io.netty.channel.socket.nio.NioServerSocketChannel.open().bind(8080).channel();

            // 注册处理程序
            ch.pipeline().addLast("handler", new ImageServerHandler());

            // 开始监听
            ch.closeFuture().sync();
        } finally {
            group.shutdownGracefully();
        }
    }
}
```

