import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.io.*;
import java.util.HashMap;
import java.util.Map;
import javax.swing.*;
import javax.swing.table.DefaultTableModel;

public class MouseRecorder {

    private static final String RECORD_FILE = "mouse_recordings.txt";
    private static final String START_COMMAND = "Shift + P";
    private static final String STOP_COMMAND = "Shift + L";
    private static boolean isRecording = false;
    private Map<String, Point> mousePositions = new HashMap<>();

    public void startRecording() {
        isRecording = true;
        System.out.println("Recording started. Press " + STOP_COMMAND + " to stop.");
    }

    public void stopRecording() {
        isRecording = false;
        System.out.println("Recording stopped.");
        saveRecordingsToFile();
    }

    private void saveRecordingsToFile() {
        try (PrintWriter writer = new PrintWriter(new FileWriter(RECORD_FILE))) {
            for (Map.Entry<String, Point> entry : mousePositions.entrySet()) {
                writer.println(entry.getKey() + ": (" + entry.getValue().x + ", " + entry.getValue().y + ")");
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public void mouseMoveListener(MouseEvent e) {
        if (isRecording) {
            mousePositions.put(Thread.currentThread().getName(), e.getPoint());
        }
    }

    public void replayMouseMovements() {
        loadRecordingsFromFile();
        JTable table = new JTable(new DefaultTableModel(new String[][] {}, new String[] {"Command", "X", "Y"}));
        for (Map.Entry<String, Point> entry : mousePositions.entrySet()) {
            table.addRow(new Object[] {entry.getKey(), entry.getValue().x, entry.getValue().y});
        }
        JScrollPane scrollPane = new JScrollPane(table);
        JFrame frame = new JFrame("Mouse Replay");
        frame.add(scrollPane);
        frame.setVisible(true);
    }

    private void loadRecordingsFromFile() {
        try (BufferedReader reader = new BufferedReader(new FileReader(RECORD_FILE))) {
            String line;
            while ((line = reader.readLine()) != null) {
                String[] parts = line.split(": ");
                mousePositions.put(parts[0], new Point(Integer.parseInt(parts[1].split(", ")[0]), Integer.parseInt(parts[1].split(", ")[1])));
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        MouseRecorder recorder = new MouseRecorder();
        MouseAdapter adapter = new MouseAdapter() {
            @Override
            public void mouseMoved(MouseEvent e) {
                if (recorder.isRecording) {
                    recorder.mouseMoveListener(e);
                }
            }
        };

        // Detect screen size and add mouse listener
        Dimension screenSize = Toolkit.getDefaultToolkit().getScreenSize();
        System.out.println("Screen size: " + screenSize.width + "x" + screenSize.height);

        // Add mouse listener to the entire screen
        MouseEvent event = new MouseEvent(screenSize.width, screenSize.height, 0, 0, 0, 0, 0, false);
        adapter.mouseMoved(event);

        // Start and stop commands
        KeyboardFocusManager.getCurrentKeyboardFocusManager().addKeyListener(new KeyAdapter() {
            @Override
            public void keyPressed(KeyEvent e) {
                if (e.getKeyCode() == KeyEvent.VK_P && e.isModifierPressed(InputEvent.SHIFT_MASK)) {
                    recorder.startRecording();
                } else if (e.getKeyCode() == KeyEvent.VK_L && e.isModifierPressed(InputEvent.SHIFT_MASK)) {
                    recorder.stopRecording();
                }
            }
        });

        // Create and show the main frame
        JFrame frame = new JFrame("Mouse Recorder");
        frame.add(new JLabel("Press " + START_COMMAND + " to start recording and " + STOP_COMMAND + " to stop."));
        frame.add(new JLabel("Replay mouse movements by clicking on the table entries."));
        frame.add(recorder.replayMouseMovements());
        frame.setVisible(true);
    }
}
