import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.Node;
import org.w3c.dom.NodeList;

import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import java.io.IOException;
import java.io.StringReader;

public class XmlParserExample {

    public static void main(String[] args) {
        String xml = "<DOCUMENT><INFO><NUMPAGES>10</NUMPAGES></INFO></DOCUMENT>";

        try {
            Document document = parseXml(xml);
            int numPages = getNumPages(document);
            System.out.println("Number of pages: " + numPages);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public static Document parseXml(String xml) throws IOException {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        DocumentBuilder builder = factory.newDocumentBuilder();
        return builder.parse(new StringReader(xml));
    }

    public static int getNumPages(Document document) {
        NodeList nodeList = document.getElementsByTagName("NUMPAGES");
        if (nodeList.getLength() > 0) {
