    try {
        const { email, password } = req.body;
        const token = await auth.authenticate(email, password);
        res.json({ token });
    } catch (error) {
        res.status(401).json({ error: error.message });
    }
});

module.exports = router;
```

#### 6. 启动服务器
在`index.js`文件中启动服务器。
```javascript
