import java.io.*;
import java.net.*;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class EcommerceChatServer {
    private ServerSocket serverSocket;
    private ExecutorService executorService;

    public EcommerceChatServer(int port) throws IOException {
        serverSocket = new ServerSocket(port);
        executorService = Executors.newCachedThreadPool();
    }

    public void start() {
        System.out.println("Server started on port " + serverSocket.getLocalPort());
        while (true) {
            Socket clientSocket = serverSocket.accept();
            executorService.execute(new ChatHandler(clientSocket));
        }
    }

    public void stop() {
        try {
            serverSocket.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
        executorService.shutdown();
    }

    private class ChatHandler implements Runnable {
        private Socket socket;

        public ChatHandler(Socket socket) {
            this.socket = socket;
        }

        @Override
        public void run() {
            try (DataInputStream in = new DataInputStream(socket.getInputStream());
                 DataOutputStream out = new DataOutputStream(socket.getOutputStream())) {

                while (true) {
                    String message = in.readUTF();
                    if (message.startsWith("CONNECT")) {
                        // Handle connection request
                        out.writeUTF("CONNECTED");
                    } else if (message.startsWith("DISCONNECT")) {
                        // Handle disconnection request
                        out.writeUTF("DISCONNECTED");
                        break;
                    } else {
                        // Handle text message
                        System.out.println("Received message: " + message);
                        out.writeUTF("Message received: " + message);
                    }
                }
            } catch (IOException e) {
                e.printStackTrace();
            } finally {
                try {
                    socket.close();
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
        }
    }
}
