public class QuickSortMutliThreading
	extends RecursiveTask<Integer> {

	int start, end;
	int[] arr;

	/**
	* Finding random pivoted and partition
	* array on a pivot.
	* There are many different
	* partitioning algorithms.
	* @param start
	* @param end
	* @param arr
	* @return
	*/
	private int partition(int start, int end,
						int[] arr)
	{

		int i = start, j = end;

		// Decide random pivot
		int pivoted = new Random()
						.nextInt(j - i)
					+ i;

		// Swap the pivoted with end
		// element of array;
		int t = arr[j];
		arr[j] = arr[pivote];
		arr[pivote] = t;
		j--;

		// Start partitioning
		while (i <= j) {

			if (arr[i] <= arr[end]) {
				i++;
				continue;
			}

			if (arr[j] >= arr[end]) {
				j--;
				continue;
			}

			t = arr[j];
			arr[j] = arr[i];
			arr[i] = t;
			j--;
			i++;
		}

		// Swap pivoted to its
		// correct position
		t = arr[j + 1];
		arr[j + 1] = arr[end];
		arr[end] = t;
		return j + 1;
	}

	// Function to implement
	// QuickSort method
	public QuickSortMutliThreading(int start,
								int end,
								int[] arr)
	{
		this.arr = arr;
		this.start = start;
		this.end = end;
	}

	@Override
	protected Integer compute()
	{
		// Base case
		if (start >= end)
			return null;

		// Find partition
		int p = partition(start, end, arr);

		// Divide array
		QuickSortMutliThreading left
			= new QuickSortMutliThreading(start,
										p - 1,
										arr);

		QuickSortMutliThreading right
			= new QuickSortMutliThreading(p + 1,
										end,
										arr);

		// Left subproblem as separate thread
		left.fork();
		right.compute();

		// Wait until left thread complete
		left.join();

		// We don't want anything as return
