```java
import java.io.*;
import java.util.Random;
import java.util.concurrent.ForkJoinPool;
import java.util.concurrent.RecursiveTask;

public class QuickSortMultiThreading extends RecursiveTask<Integer[]> {

    int start, end;
    int[] arr;

    /**
     * Finding random pivoted and partition
     * array on a pivot.
     * There are many different
     * partitioning algorithms.
     * @param start
     * @param end
     * @param arr
     * @return
     */
    private int partition(int start, int end, int[] arr) {

        int i = start, j = end;

        // Decide random pivot
        int pivoted = new Random().nextInt(j - i) + i;

        // Swap the pivoted with end
        // element of array;
        int t = arr[j];
        arr[j] = arr[pivoted];
        arr[pivoted] = t;
        j--;

        // Start partitioning
        while (i <= j) {

            if (arr[i] <= arr[end]) {
                i++;
                continue;
            }

            if (arr[j] >= arr[end]) {
                j--;
                continue;
            }

            t = arr[j];
            arr[j] = arr[i];
            arr[i] = t;
            j--;
            i++;
        }

        // Swap pivoted to its
        // correct position
        t = arr[j + 1];
        arr[j + 1] = arr[end];
        arr[end] = t;
        return j + 1;
    }

    // Function to implement
    // QuickSort method
    public QuickSortMultiThreading(int start, int end, int[] arr) {
        this.arr = arr;
        this.start = start;
        this.end = end;
    }

    @Override
    protected Integer[] compute() {
        // Base case
        if (start >= end) {
            return new Integer[] { arr[start] };
        }

        // Find partition
        int p = partition(start, end, arr);

        // Divide array
        QuickSortMultiThreading left = new QuickSortMultiThreading(start, p - 1, arr);
        QuickSortMultiThreading right = new QuickSortMultiThreading(p + 1, end, arr);

        // Left subproblem as separate thread
        if (left.compute().length > 0) {
            left.fork();
        }
        if (right.compute().length > 0) {
            right.compute();
        }

        // Wait until left thread complete
        if (left.compute().length > 0) {
            left.join();
        }

        // Combine results
        Integer[] leftResult = left.compute();
        Integer[] rightResult = right.compute();

        Integer[] result = new Integer[leftResult.length + rightResult.length];
        System.arraycopy(leftResult, 0, result, 0, leftResult.length);
        System.arraycopy(rightResult, 0, result, leftResult.length, rightResult.length);

        return result;
    }

    // Driver Code
    public static void main(String args[]) {
        int n = 7;
        int[] arr = { 54, 64, 95, 82, 12, 32, 63 };

        // Forkjoin ThreadPool to keep
        // thread creation as per resources
        ForkJoinPool pool = ForkJoinPool.commonPool();

        // Start the first thread in fork
        // join pool for range 0, n-1
        pool.invoke(new QuickSortMultiThreading(0, n - 1, arr));

        // Print sorted elements
        for (int i = 0; i < n; i++) {
            System.out.print(arr[i] + " ");
        }
    }
}
```

