```java
import org.json.JSONArray;
import org.json.JSONObject;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.Node;
import org.w3c.dom.NodeList;
import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import java.io.StringWriter;
import java.util.Iterator;

public class JsonToXml {

    public static String jsonToXml(String json) {
        JSONObject jsonObject = new JSONObject(json);
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        DocumentBuilder builder = null;
        try {
            builder = factory.newDocumentBuilder();
        } catch (Exception e) {
            e.printStackTrace();
        }
        Document document = builder.newDocument();
        Element root = document.createElement(jsonObject.getString("root"));
        document.appendChild(root);
        convertToXml(root, jsonObject);
        StringWriter sw = new StringWriter();
        document.outputXML(sw);
        return sw.toString();
    }

    private static void convertToXml(Element parent, JSONObject jsonObject) {
        Iterator<String> keys = jsonObject.keys();
        while (keys.hasNext()) {
            String key = keys.next();
            Object value = jsonObject.get(key);
            if (value instanceof JSONObject) {
                Element child = parent.getOwnerDocument().createElement(key);
                parent.appendChild(child);
                convertToXml(child, (JSONObject) value);
            } else if (value instanceof JSONArray) {
                Element child = parent.getOwnerDocument().createElement(key);
                parent.appendChild(child);
                convertArrayToXml(child, (JSONArray) value);
            } else {
                Element child = parent.getOwnerDocument().createElement(key);
                child.setTextContent(String.valueOf(value));
                parent.appendChild(child);
            }
        }
    }

    private static void convertArrayToXml(Element parent, JSONArray array) {
        for (int i = 0; i < array.length(); i++) {
            Object value = array.get(i);
            if (value instanceof JSONObject) {
                Element child = parent.getOwnerDocument().createElement(parent.getTagName());
                parent.appendChild(child);
                convertToXml(child, (JSONObject) value);
            } else {
                Element child = parent.getOwnerDocument().createElement(parent.getTagName());
                child.setTextContent(String.valueOf(value));
                parent.appendChild(child);
            }
        }
    }

    public static void main(String[] args) {
        String json = "{\"root\":{\"name\":\"John Doe\",\"age\":30,\"address\":{\"street\":\"123 Main St\",\"city\":\"Anytown\",\"zip\":12345},\"phones\":[\"123-456-7890\",\"987-654-3210\"]}}";
        String xml = jsonToXml(json);
        System.out.println(xml);
    }
}
```

这个程序首先解析JSON字符串，然后递归地将JSON对象转换为XML元素。对于数组，它会创建一个包含相同标签的元素，并将数组中的每个元素作为子元素添加。

请注意，这个示例假设JSON中的根元素是`root`，并且JSON结构是相对简单的。对于更复杂的情况，你可能需要对代码进行一些调整。

