### 1. Classe `Sondage`

La classe `Sondage` représente le sondage lui-même et stocke les propositions et les votes.

```java
import java.util.HashMap;
import java.util.Map;

public class Sondage {
    private Map<String, Integer> propositions;

    public Sondage() {
        this.propositions = new HashMap<>();
    }

    public void ajouterProposition(String proposition) {
        propositions.put(proposition, 0);
    }

    public void voter(String proposition) {
        if (propositions.containsKey(proposition)) {
            propositions.put(proposition, propositions.get(proposition) + 1);
        } else {
            throw new IllegalArgumentException("Proposition non trouvée");
        }
    }

    public String getResultat() {
        int maxVotes = 0;
        String resultat = "";
        for (Map.Entry<String, Integer> entry : propositions.entrySet()) {
            if (entry.getValue() > maxVotes) {
                maxVotes = entry.getValue();
                resultat = entry.getKey();
            }
        }
        return resultat;
    }

    public Map<String, Integer> getPropositions() {
        return propositions;
    }
}
```

### 2. Classe `Serveur`

La classe `Serveur` gère les requêtes des clients et utilise un `ExecutorService` pour gérer les threads.

```java
import java.io.*;
import java.net.*;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class Serveur {
    private ServerSocket serverSocket;
    private ExecutorService executor;
    private Sondage sondage;

    public Serveur(int port) throws IOException {
        this.serverSocket = new ServerSocket(port);
        this.executor = Executors.newFixedThreadPool(10);
        this.sondage = new Sondage();
    }

    public void start() {
        System.out.println("Serveur démarré sur le port " + serverSocket.getLocalPort());
        while (true) {
            try {
                Socket clientSocket = serverSocket.accept();
                executor.execute(new ClientHandler(clientSocket));
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    private class ClientHandler implements Runnable {
        private Socket socket;

        public ClientHandler(Socket socket) {
            this.socket = socket;
        }

        @Override
        public void run() {
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(socket.getInputStream()));
                 PrintWriter writer = new PrintWriter(socket.getOutputStream(), true)) {

                String request;
                while ((request = reader.readLine()) != null) {
                    switch (request) {
                        case "candidats":
                            writer.println(sondage.getPropositions().keySet());
                            break;
                        case "vote " + Integer.parseInt(reader.readLine()):
                            String proposition = reader.readLine();
                            try {
                                sondage.voter(proposition);
                                writer.println("OK");
                            } catch (IllegalArgumentException e) {
                                writer.println("ERR " + e.getMessage());
                            }
                            break;
                        case "resultat":
                            writer.println("Resultat: " + sondage.getResultat());
                            break;
                        default:
                            writer.println("ERR Requête non reconnue");
                    }
                }
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }
}
```

### 3. Classe `Client`

La classe `Client` gère les requêtes du client et communique avec le serveur.

```java
import java.io.*;
import java.net.Socket;

public class Client {
    private Socket socket;
    private BufferedReader reader;
    private PrintWriter writer;

    public Client(String host, int port) throws IOException {
        this.socket = new Socket(host, port);
        this.reader = new BufferedReader(new InputStreamReader(socket.getInputStream()));
        this.writer = new PrintWriter(socket.getOutputStream(), true);
    }

    public void envoyerRequete(String requete) throws IOException {
        writer.println(requete);
        writer.flush();
    }

    public String recevoirReponse() throws IOException {
        return reader.readLine();
    }

    public void fermerConnexion() throws IOException {
        socket.close();
    }
}
```

