```csharp
using System;
using System.Net;
using System.Net.Sockets;
using System.Text;
using System.Threading.Tasks;

namespace VpnServer
{
    class VpnServer
    {
        private TcpListener _listener;
        private TcpClient _client;
        private NetworkStream _stream;
        private StreamReader _reader;
        private StreamWriter _writer;

        public VpnServer(int port)
        {
            _listener = new TcpListener(IPAddress.Any, port);
            _listener.Start();
            Console.WriteLine("VPN Server started on port " + port);
        }

        public void Start()
        {
            while (true)
            {
                _client = _listener.AcceptTcpClient();
                _stream = _client.GetStream();
                _reader = new StreamReader(_stream);
                _writer = new StreamWriter(_stream);

                Task.Run(() => HandleClient());
            }
        }

        private async Task HandleClient()
        {
            try
            {
                string message = await _reader.ReadLineAsync();
                Console.WriteLine("Received: " + message);

                // 这里假设我们需要转发到目标服务器
                string targetServer = "target.com";
                int targetPort = 80;
                await ForwardToTargetServer(message, targetServer, targetPort);
            }
            catch (Exception ex)
            {
                Console.WriteLine("Error handling client: " + ex.Message);
            }
            finally
            {
                _client.Close();
                _stream.Close();
                _reader.Dispose();
                _writer.Dispose();
            }
        }

        private async Task ForwardToTargetServer(string message, string targetServer, int targetPort)
        {
            using (TcpClient targetClient = new TcpClient(targetServer, targetPort))
            {
                using (NetworkStream targetStream = targetClient.GetStream())
                {
                    _writer.WriteLine(message);
                    await _writer.FlushAsync();

                    string response = await _reader.ReadLineAsync();
                    Console.WriteLine("Response from target server: " + response);
                }
            }
        }
    }
}
