import javax.servlet.ServletException;
import javax.servlet.annotation.WebServlet;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.io.PrintWriter;

@WebServlet("/DivideServlet")
public class DivideServlet extends HttpServlet {
    protected void doPost(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        response.setContentType("text/html");
        PrintWriter out = response.getWriter();

        // 获取表单数据
        String dividendStr = request.getParameter("dividend");
        String divisorStr = request.getParameter("divisor");

        try {
            // 尝试将字符串转换为double类型
            double dividend = Double.parseDouble(dividendStr);
            double divisor = Double.parseDouble(divisorStr);

            // 检查除数是否为0
            if (divisor == 0) {
                out.println("Error: Divisor cannot be zero.");
            } else {
                // 进行除法运算
                double result = dividend / divisor;
                out.println("Result: " + result);
            }
        } catch (NumberFormatException e) {
            out.println("Error: Please enter valid numbers.");
        }

        out.close();
    }
}
```

