```java
import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.Node;
import org.w3c.dom.NodeList;

public class XmlExtractor {

    public static String extractXml(String xmlString, String tagName) {
        try {
            // Create a DocumentBuilder to parse the XML string
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            DocumentBuilder builder = factory.newDocumentBuilder();
            Document document = builder.parse(new java.io.ByteArrayInputStream(xmlString.getBytes()));

            // Find the element with the specified tag name
            NodeList nodeList = document.getElementsByTagName(tagName);
            if (nodeList.getLength() > 0) {
                Node node = nodeList.item(0);
                if (node.getNodeType() == Node.ELEMENT_NODE) {
                    Element element = (Element) node;
                    // Extract the text content of the element
                    return element.getTextContent();
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
        return null;
    }

    public static void main(String[] args) {
        String xml = "<root><person><name>John</name><age>30</age></person></root>";
        String extractedText = extractXml(xml, "name");
        System.out.println(extractedText); // Output: John
    }
}
```

In this code, the `extractXml` method takes an XML string and a tag name as input. It uses the `DocumentBuilder` class to parse the XML string and then finds the element with the specified tag name. The text content of that element is then extracted and returned as a string.

You can customize the `tagName` variable to extract different pieces of XML from the string. Make sure to handle exceptions appropriately, especially when parsing XML, as it can be sensitive to errors.

