Implementing a blockchain from scratch in Java is a complex but rewarding project. Here's a simplified example to get you started. This example will cover the core components of a blockchain: blocks, a blockchain data structure, and basic functionalities like adding blocks and verifying the chain.

```java
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;

class Block {
    private String previousHash;
    private String data;
    private String hash;
    private long timestamp;

    public Block(String data, String previousHash) {
        this.data = data;
        this.previousHash = previousHash;
        this.timestamp = System.currentTimeMillis();
        this.calculateHash();
    }

    public String getPreviousHash() {
        return previousHash;
    }

    public String getData() {
        return data;
    }

    public String getHash() {
        return hash;
    }

    public long getTimestamp() {
        return timestamp;
    }

    private void calculateHash() {
        String blockData = data + timestamp + previousHash;
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hashBytes = digest.digest(blockData.getBytes(StandardCharsets.UTF_8));
            this.hash = bytesToHex(hashBytes);
        } catch (NoSuchAlgorithmException e) {
            e.printStackTrace();
        }
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder hexString = new StringBuilder();
        for (byte b : bytes) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) {
                hexString.append('0');
            }
            hexString.append(hex);
        }
        return hexString.toString();
    }
}

class Blockchain {
    private List<Block> chain;

    public Blockchain() {
        this.chain = new ArrayList<>();
        if (chain.isEmpty()) {
            this.createGenesisBlock();
        }
    }

    public void createGenesisBlock() {
        Block genesisBlock = new Block("Genesis Block", "0");
        chain.add(genesisBlock);
    }

    public void addBlock(String data) {
        Block newBlock = new Block(data, getPreviousHash());
        chain.add(newBlock);
    }

    public String getPreviousHash() {
        if (chain.size() < 2) {
            return "0";
        }
        return chain.get(chain.size() - 2).getHash();
    }

    public boolean isChainValid() {
        for (int i = 1; i < chain.size(); i++) {
            Block currentBlock = chain.get(i);
            Block previousBlock = chain.get(i - 1);

            if (!currentBlock.getHash().equals(currentBlock.calculateHash())) {
                return false;
            }

            if (!currentBlock.getPreviousHash().equals(previousBlock.getHash())) {
                return false;
            }
        }
        return true;
    }

    public void printChain() {
        for (Block block : chain) {
            System.out.println("Hash: " + block.getHash());
            System.out.println("Data: " + block.getData());
            System.out.println("Timestamp: " + block.getTimestamp());
            System.out.println("Previous Hash: " + block.getPreviousHash());
            System.out.println("-------------------------");
        }
    }
}

public class Main {
    public static void main(String[] args) {
        Blockchain blockchain = new Blockchain();

        blockchain.addBlock("Transaction 1");
        blockchain.addBlock("Transaction 2");
        blockchain.addBlock("Transaction 3");

        System.out.println("Is Blockchain Valid? " + blockchain.isChainValid());

        blockchain.printChain();
    }
}
```

**Explanation:**

