```java
import java.io.IOException;
import java.net.Socket;
import java.net.UnknownHostException;

public class PortChecker {

    public static boolean isPortOpen(String host, int port) {
        Socket socket = null;
        try {
            socket = new Socket(host, port);
            socket.setSoTimeout(5000); // 设置超时时间，单位为毫秒
            socket.connect(new java.net.InetSocketAddress(host, port), 5000); // 连接并设置超时时间
            return true;
        } catch (UnknownHostException e) {
            System.out.println("UnknownHostException: " + e.getMessage());
        } catch (IOException e) {
            System.out.println("Port is not open or unreachable: " + e.getMessage());
        } finally {
            if (socket != null) {
                try {
                    socket.close();
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
        }
        return false;
    }

    public static void main(String[] args) {
        String host = "www.example.com"; // 替换为你要检查的服务器地址
        int port = 80; // 替换为你要检查的端口号

        if (isPortOpen(host, port)) {
            System.out.println(host + ":" + port + " is open.");
        } else {
            System.out.println(host + ":" + port + " is not open.");
        }
    }
}
```

### 代码解释：
1. **Socket类**：Java的Socket类用于创建网络连接，可以用来尝试连接到指定的服务器和端口。
