        customers.add(new Customer("Customer4", 400.0, 4));
        customers.add(new Customer("Customer5", 500.0, 1));

        for (Customer customer : customers) {
            for (int i = 0; i < customer.getDepositCount(); i++) {
                double amount = customer.getDepositAmount();
                account.deposit(amount);
                System.out.println("Customer " + customer.getName() + " deposited " + amount + ". Current balance: " + account.getBalance());
            }
        }

