```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Wireframe Grid</title>
    <style>
        body {
            margin: 0;
            display: flex;
            justify-content: center;
            align-items: center;
            height: 100vh;
            background-color: #f0f0f0;
        }
        canvas {
            border: 1px solid #000;
        }
    </style>
</head>
<body>
    <canvas id="canvas" width="800" height="600"></canvas>
    <script>
        const canvas = document.getElementById('canvas');
        const ctx = canvas.getContext('2d');
        const canvasWidth = canvas.width;
        const canvasHeight = canvas.height;

        // Arrays to store the 3D model, grid points, and drawn lines
        const model = [];
        const gridPoints = [];
        const drawnLines = [];

        // Snap points for grid
        const snapPoints = [
            { x: 0, y: 0, z: 0 },
            { x: 0, y: 0, z: 1 },
            { x: 0, y: 1, z: 0 },
            { x: 0, y: 1, z: 1 },
            { x: 1, y: 0, z: 0 },
            { x: 1, y: 0, z: 1 },
            { x: 1, y: 1, z: 0 },
            { x: 1, y: 1, z: 1 },
        ];

        // Mouse interaction variables
        let isDrawing = false;
        let currentLine = [];
        let currentSnapPoint = null;

        // Initialize the grid points
        for (let x = 0; x <= 10; x++) {
            for (let y = 0; y <= 10; y++) {
                for (let z = 0; z <= 10; z++) {
                    gridPoints.push({ x: x, y: y, z: z });
                }
            }
        }

        // Function to draw the grid
        function drawGrid() {
            ctx.clearRect(0, 0, canvasWidth, canvasHeight);
            ctx.strokeStyle = 'black';
            ctx.lineWidth = 1;

            // Draw grid lines
            for (let x = 0; x <= 10; x++) {
                const xPos = x * 80;
                ctx.beginPath();
                ctx.moveTo(xPos, 0);
                ctx.lineTo(xPos, canvasHeight);
                ctx.stroke();

                ctx.beginPath();
                ctx.moveTo(0, xPos);
                ctx.lineTo(canvasWidth, xPos);
                ctx.stroke();
            }
        }

        // Function to draw the 3D model
        function drawModel() {
            ctx.strokeStyle = 'black';
            ctx.lineWidth = 1;

            for (let i = 0; i < model.length; i++) {
                const line = model[i];
                ctx.beginPath();
                ctx.moveTo(line[0].x * 80, line[0].y * 60);
                ctx.lineTo(line[1].x * 80, line[1].y * 60);
                ctx.stroke();
            }
        }

        // Function to snap a point to the grid
        function snapPoint(point) {
            const snappedPoint = snapPoints.find(p =>
                Math.abs(p.x - point.x) < 1e-6 &&
                Math.abs(p.y - point.y) < 1e-6 &&
                Math.abs(p.z - point.z) < 1e-6
            );
            return snappedPoint || point;
        }

        // Function to handle mouse events
        function handleMouse(event) {
            const mouseX = event.clientX - canvas.getBoundingClientRect().left;
            const mouseY = event.clientY - canvas.getBoundingClientRect().top;

            if (event.type === 'mousedown') {
                isDrawing = true;
                currentLine = [{ x: mouseX, y: mouseY, z: 0 }];
                currentSnapPoint = snapPoint({ x: mouseX, y: mouseY, z: 0 });
            } else if (event.type === 'mousemove' && isDrawing) {
                currentLine.push({ x: mouseX, y: mouseY, z: 0 });
                currentLine.push(snapPoint({ x: mouseX, y: mouseY, z: 0 }));
            } else if (event.type === 'mouseup') {
                isDrawing = false;
                if (currentLine.length > 1) {
                    drawnLines.push(currentLine);
                    model.push(currentLine);
                }
            }
        }

        // Add event listeners
        canvas.addEventListener('mousedown', handleMouse);
        canvas.addEventListener('mousemove', handleMouse);
        canvas.addEventListener('mouseup', handleMouse);
        canvas.addEventListener('mouseout', () => isDrawing = false);

        // Initial draw
        drawGrid();

        // Example usage: Add a few lines to the model
        drawnLines.push([{ x: 0, y: 0, z: 0 }, { x: 100, y: 0, z: 0 }]);
        drawnLines.push([{ x: 0, y: 0, z: 0 }, { x: 0, y: 100, z: 0 }]);

        // Redraw the model
        drawModel();
    </script>
</body>
</html>
```

### Explanation:
1. **HTML Structure**: The HTML file sets up a canvas element where the 3D wireframe will be drawn.
2. **CSS**: Basic styling is applied to center the canvas and set a background color.
3. **JavaScript**:
   - **Arrays**:
     - `model`: Stores the 3D wireframe lines as arrays of points.
     - `gridPoints`: A large array of points representing the grid.
     - `drawnLines`: Stores the lines that have been drawn.
   - **Snap Points**: An array of `snapPoints` helps in snapping lines to the grid.
   - **Mouse Interaction**:
     - `isDrawing`: Flag to track if a line is being drawn.
     - `currentLine`: Array to store the points of the current line.
     - `currentSnapPoint`: The snapped point for the current line.
   - **Drawing Functions**:
     - `drawGrid`: Draws the grid lines on the canvas.
     - `drawModel`: Draws the 3D wireframe model using the `model` array.
   - **Snap Point Function**: `snapPoint` finds the closest snap point to a given point.
   - **Mouse Event Handlers**:
     - `handleMouse`: Handles mouse down, move, and up events to draw lines and snap points.
   - **Event Listeners**: Adds event listeners to the canvas for mouse interactions.
   - **Initial Draw**: Calls `drawGrid` to initialize the grid and adds some example lines to the `model`.

