const startButton = document.getElementById('startButton');
const bpmDisplay = document.getElementById('bpmDisplay');
const audioContext = document.getElementById('audioContext');
let analyserNode;
let dataArray;
let bpm = 0;
let isListening = false;

function startListening() {
    if (!isListening) {
        isListening = true;
        navigator.mediaDevices.getUserMedia({ audio: true })
            .then(stream => {
                const audioContext = new AudioContext();
                const source = audioContext.createMediaStreamSource(stream);
                const analyser = audioContext.createAnalyser();
                analyser.fftSize = 2048;
                dataArray = new Uint8Array(analyser.fftSize / 2);

                source.connect(analyser);
                analyser.connect(audioContext.destination);

                const sampleRate = audioContext.sampleRate;
                const bufferLength = analyser.fftSize;
                const samplesPerBeat = 4; // Assuming 4 beats per bar for a common tempo of 120 BPM

                function updateBPM() {
                    if (isListening) {
                        analyser.getByteFrequencyData(dataArray);
                        const maxIndex = dataArray.indexOf(Math.max(...dataArray));
                        const frequency = maxIndex / bufferLength * sampleRate;
                        const beatsPerMinute = 60000 / (frequency * samplesPerBeat);
                        bpm = Math.round(beatsPerMinute);
                        bpmDisplay.textContent = `BPM: ${bpm}`;
                        requestAnimationFrame(updateBPM);
                    }
                }

                updateBPM();
            })
            .catch(error => {
                console.error('Error accessing microphone:', error);
            });
    } else {
        alert('Already listening. Stop listening first.');
    }
}

