Aby szyfrować pliki w Node.js, możesz wykorzystać moduł `crypto`, który jest częścią standardowej biblioteki Node.js. Poniżej jest przykładowy kod, który demonstratesz szyfrowanie pliku za pomocą algorytmu AES-256 w trybie CBC (Cipher Block Chaining).

```javascript
const fs = require('fs');
const crypto = require('crypto');

// Konfiguracja
const inputFilePath = 'plik.js';
const outputFilePath = 'plik_zaszyfrowany.js';
const key = 'twoja_sila_kluczowa_256bit'; // 256 bitów (32 bajty)
const iv = 'twoj_init_vector_16bit'; // 16 bajtów (128 bitów)

// Funkcja do szyfrowania pliku
function encryptFile(inputFilePath, outputFilePath, key, iv) {
  const cipher = crypto.createCipheriv('aes-256-cbc', Buffer.from(key), Buffer.from(iv));
  const input = fs.readFileSync(inputFilePath);
  const encrypted = cipher.update(input);
  encrypted.push(cipher.final());

  fs.writeFileSync(outputFilePath, encrypted);
  console.log(`Plik ${inputFilePath} został zaszyfrowany i zapisany jako ${outputFilePath}`);
}

// Funkcja do odzyfrowania pliku
function decryptFile(inputFilePath, outputFilePath, key, iv) {
  const decipher = crypto.createDecipheriv('aes-256-cbc', Buffer.from(key), Buffer.from(iv));
  const input = fs.readFileSync(inputFilePath);
  let decrypted = decipher.update(input);
  decrypted = Buffer.concat([decrypted, decipher.final()]);

  fs.writeFileSync(outputFilePath, decrypted.toString());
  console.log(`Plik ${inputFilePath} został odzyfrowany i zapisany jako ${outputFilePath}`);
}

// Szyfrowanie pliku
encryptFile(inputFilePath, outputFilePath, key, iv);

// Odzyfrowanie pliku (po zaszyfrowaniu)
// decryptFile(outputFilePath, inputFilePath, key, iv);
```

### Wskazówki:
1. **Klucz i IV**: Klucz i Initial Vector (IV) muszą być takie same podczas szyfrowania i odzyfrowania.
2. **Bezpieczeństwo**: Klucz powinien być długi i losowy, aby zapewnić wysoką jakość szyfrowania.
3. **Odzyfrowanie**: Pamiętaj, że po zaszyfrowaniu pliku musisz go odzyfrować, aby odzyskać oryginalny plik.

### Wpływ na plik:
- **Szyfrowanie**: Plik `plik.js` zostanie zaszyfrowany i zapisany jako `plik_zaszyfrowany.js`.
- **Odzyfrowanie**: Aby odzyskać oryginalny plik, musisz odzyfrować `plik_zaszyfrowany.js` i zapisać go jako `plik.js`.

