function calculateResult(num1, num2) {
  let steps = [];
  let currentNum = num2;
  let divisor = num1;

  while (currentNum !== 0) {
    const remainder = currentNum % divisor;
    steps.push(`${divisor} = 1 * ${currentNum} + ${remainder}`);
    currentNum = divisor;
    divisor = remainder;
  }

  let finalResult = `1 = 1 * ${currentNum} - 1 * ${steps[steps.length - 1]}`;
  for (let i = steps.length - 2; i >= 0; i--) {
    finalResult = steps[i];
    steps[i] = `1 = 1 * ${steps[i]} - 1 * ${steps[i + 1]}`;
  }

  return finalResult;
}
