```javascript
/**
 * Manages WebSocket connections for receiving and sending data.
 * @class
 */
class WebSocketManager {
  /**
   * Initializes the WebSocketManager instance.
   * @constructor
   */
  constructor() {
    this.emitter = mitt();
  }

  /**
   * Opens a WebSocket connection to the specified URL.
   * @method
   */
  open() {
    this.socket = new WebSocket('ws://owbalancer.ddns.net:8765/site');
    const self = this;
    this.socket.addEventListener('message', (msg) => {
      const json = JSON.parse(msg.data);
      const { action, uuid, factory, inventory } = json;
      if (action === 'update_station') {
        self.emitter.emit('update_station', { uuid });
      }
      if (action === 'update_station_list') {
        self.emitter.emit('update_station_list');
      }
      if (action === 'update_inventory') {
        self.emitter.emit('update_inventory', { factory_uuid: factory, inventory_name: inventory });
      }
    });
  }

  /**
   * Sends a message over the WebSocket connection.
   * @method
   * @param {Object} data - The data to be sent.
   */
  sendMessage(data) {
    this.socket.send(JSON.stringify(data));
  }
}

/**
 * Export the WebSocketManager instance for easy access.
 * @type {WebSocketManager}
 */
export const websocketApi = new WebSocketManager();
