const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');
const startButton = document.getElementById('start-button');
const scoreDisplay = document.getElementById('score');
let score = 0;
let button = {
    x: 300,
    y: 300,
    radius: 50,
    speed: 5,
    direction: Math.random() * 2 * Math.PI, // 随机方向
    isMoving: false
};
let mouse = {
    x: 0,
    y: 0
};
let gameRunning = false;

function drawButton() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.beginPath();
    ctx.arc(button.x, button.y, button.radius, 0, 2 * Math.PI);
    ctx.fillStyle = 'black';
    ctx.fill();
    ctx.closePath();
}

function moveButton() {
    if (!button.isMoving) return;
    button.x += button.speed * Math.cos(button.direction);
    button.y += button.speed * Math.sin(button.direction);
    if (button.x - button.radius < 0 || button.x + button.radius > canvas.width) {
        button.direction = button.direction + Math.PI; // 反向
    }
    if (button.y - button.radius < 0 || button.y + button.radius > canvas.height) {
        button.direction = button.direction + Math.PI; // 反向
    }
}

function checkCollision() {
    const dx = mouse.x - button.x;
    const dy = mouse.y - button.y;
    const distance = Math.sqrt(dx * dx + dy * dy);
    if (distance < button.radius) {
        score++;
        scoreDisplay.innerText = `Score: ${score}`;
        button.isMoving = false;
        button.direction = Math.random() * 2 * Math.PI; // 复位方向
    }
}

function update() {
    if (!gameRunning) return;
    drawButton();
    moveButton();
    checkCollision();
    requestAnimationFrame(update);
}

canvas.addEventListener('mousemove', (e) => {
    mouse.x = e.clientX;
    mouse.y = e.clientY;
});

startButton.addEventListener('click', () => {
    gameRunning = true;
