В Node.js, когда используется Express.js для создания API, а SQLite3 для работы с базой данных, контроллеры (`controllers`), модели (`models`), и другие компоненты, такие как роутеры (`routers`), помогают организовывать и структурировать код. В этом примере я покажу, как используются контроллеры и модели при авторизации пользователя с использованием Express.js и SQLite3.

### 1. Модели (Models)

Модели представляют собой классы, которые описывают структуру данных в базе данных. В нашем случае мы будем использовать SQLite3 для хранения информации о пользователях.

```javascript
// models/user.js
const sqlite3 = require('sqlite3').verbose();
const { open } = require('sqlite');
const path = require('path');

const dbPath = path.join(__dirname, '../db.sqlite');

async function initDB() {
    const db = await open({ filename: dbPath });
    db.run('CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT UNIQUE, password TEXT)');
    return db;
}

module.exports = {
    initDB,
    findUserByUsername: async (username) => {
        const db = await initDB();
        const [user] = await db.all('SELECT * FROM users WHERE username = ?', [username]);
        db.close();
        return user;
    },
    createUser: async (username, password) => {
        const db = await initDB();
        db.run('INSERT INTO users (username, password) VALUES (?, ?)', [username, password]);
        db.close();
    }
};
```

### 2. Контроллеры (Controllers)

Контроллеры обрабатывают HTTP-запросы и передают их в модели для работы с базой данных.

```javascript
// controllers/auth.js
const express = require('express');
const router = express.Router();
const { findUserByUsername, createUser } = require('../models/user');

router.post('/register', async (req, res) => {
    try {
        const { username, password } = req.body;
        if (!username || !password) {
            return res.status(400).json({ error: 'Username and password are required' });
        }
        await createUser(username, password);
        res.status(201).json({ message: 'User registered successfully' });
    } catch (error) {
        res.status(500).json({ error: 'Internal server error' });
    }
});

router.post('/login', async (req, res) => {
    try {
        const { username, password } = req.body;
        if (!username || !password) {
            return res.status(400).json({ error: 'Username and password are required' });
        }
        const user = await findUserByUsername(username);
        if (!user || user.password !== password) {
            return res.status(401).json({ error: 'Invalid credentials' });
        }
        res.json({ message: 'Logged in successfully', user });
    } catch (error) {
        res.status(500).json({ error: 'Internal server error' });
    }
});

module.exports = router;
```

### 3. Роутеры (Routers)

Роутеры объединяют контроллеры и предоставляют URL-адрес для доступа к ним.

```javascript
// routes/auth.js
const express = require('express');
const authController = require('../controllers/auth');

const router = express.Router();

router.use('/register', authController);
router.use('/login', authController);

module.exports = router;
```

### 4. Использование в Express.js

В вашем main-файле (например, `app.js`) вы можете использовать роутеры для организации маршрутов и подключения контроллеров.

```javascript
// app.js
const express = require('express');
const sqlite3 = require('sqlite3').verbose();
const path = require('path');
const { open } = require('sqlite');
const authRouter = require('./routes/auth');
const { initDB } = require('./models/user');

const dbPath = path.join(__dirname, 'db.sqlite');

async function setupDB() {
    const db = await open({ filename: dbPath });
    db.close();
}

const app = express();
app.use(express.json());

await setupDB();

app.use('/api/auth', authRouter);

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
    console.log(`Server is running on port ${PORT}`);
});
```

### 5. В заключение

- **Модели (`models`)** — описывают структуру данных и предоставляют методы для работы с базой данных.
- **Контроллеры (`controllers`)** — обрабатывают HTTP-запросы, передают их в модели и возвращают ответы.
- **Роутеры (`routers`)** — объединяют контроллеры и предоставляют URL-адрес для доступа к ним.

В этом примере мы использовали SQLite3 для хранения информации о пользователях, а Express.js для создания API. Контроллеры обрабатывают регистрацию и авторизацию пользователей, а модели и роутеры помогают организовывать и структурировать код.

