```javascript
const costInput = document.getElementById('cost');
const markupInput = document.getElementById('markupPercentage');
const resultDiv = document.getElementById('result');
const markupChart = document.getElementById('markupChart');

function calculateMarkup() {
    const cost = parseFloat(costInput.value);
    const markupPercentage = parseFloat(markupInput.value);

    if (isNaN(cost) || isNaN(markupPercentage)) {
        resultDiv.textContent = 'Please enter valid numbers.';
        return;
    }

    const markupAmount = (cost * markupPercentage) / 100;
    const totalPrice = cost + markupAmount;

    resultDiv.textContent = `Total Price: $${totalPrice.toFixed(2)}`;

    // Display chart
    const ctx = markupChart.getContext('2d');
    new Chart(ctx, {
        type: 'bar',
        data: {
            labels: ['Cost', 'Markup', 'Total'],
            datasets: [{
                label: 'Prices',
                data: [cost, markupAmount, totalPrice],
                backgroundColor: ['#007BFF', '#FF9900', '#3498DB'],
                borderWidth: 1
            }]
        },
        options: {
            scales: {
                y: {
                    beginAtZero: true
                }
            }
        }
    });
}
```

