Creating a basic Snake game using HTML, CSS, and JavaScript is a fun project to get started with web development. Below is a simple implementation of the Snake game. This version will be a basic console-based game where the player controls the snake using the arrow keys to move it, and it eats dots to grow.

### HTML (index.html)
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Snake Game</title>
    <link rel="stylesheet" href="styles.css">
</head>
<body>
    <div id="game-container">
        <canvas id="gameCanvas" width="400" height="400"></canvas>
    </div>
    <script src="script.js"></script>
</body>
</html>
```

### CSS (styles.css)
```css
body {
    display: flex;
    justify-content: center;
    align-items: center;
    height: 100vh;
    margin: 0;
    background-color: #f0f0f0;
}

#game-container {
    position: relative;
    width: 400px;
    height: 400px;
    background-color: #fff;
    border: 1px solid #000;
}

#gameCanvas {
    width: 100%;
    height: 100%;
    background-color: #000;
}
```

### JavaScript (script.js)
```javascript
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

const grid = 10;
const canvasWidth = canvas.width;
const canvasHeight = canvas.height;

let snake = [
    { x: 5 * grid, y: 5 * grid },
    { x: 4 * grid, y: 5 * grid },
    { x: 3 * grid, y: 5 * grid },
    { x: 2 * grid, y: 5 * grid },
    { x: 1 * grid, y: 5 * grid }
];

let direction = 'RIGHT';
let speed = 100;
let food = { x: Math.floor(Math.random() * canvasWidth / grid) * grid, y: Math.floor(Math.random() * canvasHeight / grid) * grid };

let score = 0;

document.addEventListener('keydown', changeDirection);

function changeDirection(event) {
    if (event.keyCode === 37 && direction !== 'RIGHT') direction = 'LEFT';
    if (event.keyCode === 38 && direction !== 'DOWN') direction = 'UP';
    if (event.keyCode === 39 && direction !== 'LEFT') direction = 'RIGHT';
    if (event.keyCode === 40 && direction !== 'UP') direction = 'DOWN';
}

function drawGame() {
    ctx.clearRect(0, 0, canvasWidth, canvasHeight);

    // Draw food
    ctx.fillStyle = 'red';
    ctx.fillRect(food.x, food.y);

    // Draw snake
    ctx.fillStyle = 'green';
    snake.forEach(segment => {
        ctx.fillRect(segment.x, segment.y);
    });

    // Draw score
    ctx.fillStyle = 'white';
    ctx.font = '16px Arial';
    ctx.fillText(`Score: ${score}`, 10, 20);
}

function moveSnake() {
    const head = { ...snake[0] };
    if (direction === 'RIGHT') head.x += grid;
    if (direction === 'LEFT') head.x -= grid;
    if (direction === 'UP') head.y -= grid;
    if (direction === 'DOWN') head.y += grid;

    snake.unshift(head);

    if (head.x === food.x && head.y === food.y) {
        food.x = Math.floor(Math.random() * canvasWidth / grid) * grid;
        food.y = Math.floor(Math.random() * canvasHeight / grid) * grid;
        score++;
    } else {
        snake.pop();
    }
}

function gameLoop() {
    moveSnake();
    drawGame();
    setTimeout(gameLoop, speed);
}

gameLoop();
```

### Explanation
1. **HTML**: Sets up the basic structure of the game, including a canvas element where the game will be rendered.
2. **CSS**: Styles the canvas to fit the center of the page and gives it a black background.
3. **JavaScript**:
   - **Snake Initialization**: Initializes the snake's position, direction, speed, and food position.
   - **Key Event Listener**: Listens for arrow key presses to change the snake's direction.
   - **Draw Game**: Clears the canvas, draws the food, and the snake.
   - **Move Snake**: Moves the snake based on the current direction, checks for food, and updates the score.
   - **Game Loop**: Continuously calls `moveSnake` and `drawGame` to update the game state and render it.

To play the game, simply open the `index.html` file in a web browser. Use the arrow keys to control the snake. Enjoy!

