### Step 3: Create the Component
Create a new component, for example, `AttachmentPopup.js`:

```jsx
// components/AttachmentPopup.js
import React, { useState } from 'react';
import { Button, Modal, Form, Alert } from 'react-bootstrap';

const AttachmentPopup = ({ isOpen, onClose, onAttachmentSubmit }) => {
  const [selectedFile, setSelectedFile] = useState(null);
  const [attachmentError, setAttachmentError] = useState(null);

  const handleFileChange = (e) => {
    setSelectedFile(e.target.files[0]);
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (selectedFile) {
      onAttachmentSubmit(selectedFile);
      setSelectedFile(null);
      setAttachmentError(null);
    } else {
      setAttachmentError('Please select a file.');
    }
  };

  return (
    <Modal show={isOpen} onHide={onClose}>
      <Modal.Header closeButton>
        <Modal.Title>Attach Document</Modal.Title>
      </Modal.Header>
      <Modal.Body>
        <Form onSubmit={handleSubmit}>
          <Form.Group controlId="formFile">
            <Form.Label>Select a file</Form.Label>
            <Form.Control type="file" onChange={handleFileChange} />
          </Form.Group>
          {attachmentError && <Alert variant="danger">{attachmentError}</Alert>}
          <Button variant="primary" type="submit" className="mt-3">
            Attach
          </Button>
        </Form>
      </Modal.Body>
      <Modal.Footer>
        <Button variant="secondary" onClick={onClose}>
          Close
        </Button>
      </Modal.Footer>
    </Modal>
  );
};

export default AttachmentPopup;
```

