```

### 2. Создание `index.js` (или `index.ts`)

Создаем файл `index.js` (или `index.ts`) в папке `src`:

```javascript
// index.js (или index.ts)

import { fromEvent } from 'rxjs';
import { ajax } from 'rxjs/ajax';
import { map, switchMap } from 'rxjs/operators';

const showDataBtn = document.getElementById('showDataBtn');
const deleteBtn = document.getElementById('deleteBtn');
const dataContainer = document.getElementById('dataContainer');

const getData = () => {
    return ajax.getJSON('https://example.com/data.json'); // Замените на реальный URL
};

const deleteLastItem = () => {
    const items = Array.from(dataContainer.querySelectorAll('p')).reverse();
    if (items.length > 0) {
        dataContainer.removeChild(items[0]);
    }
};

showDataBtn.addEventListener('click', () => {
    getData()
        .pipe(
            map(response => response.response.data),
            map(data => `<p>${JSON.stringify(data, null, 2)}</p>`)
        )
        .subscribe(item => {
            dataContainer.innerHTML += item;
        });
});

deleteBtn.addEventListener('click', () => {
    deleteLastItem();
});

// Обработка события с помощью RxJS
fromEvent(document, 'click')
    .pipe(
        filter(event => event.target.id === 'showDataBtn'),
        switchMap(() => getData())
    )
    .subscribe(response => {
        const data = response.response.data;
        dataContainer.innerHTML = `<p>${JSON.stringify(data, null, 2)}</p>`;
    });
```

### 3. Обработка событий с помощью RxJS

В `index.js` (или `index.ts`) мы используем `fromEvent` для обработки события щелчка по кнопке `showDataBtn`. Мы также используем `switchMap` для трансформации Observable, полученного с помощью `ajax.getJSON`, в Observable, который отображает полученные данные на странице.

### 4. Удаление последней строки

Мы также добавляем обработку события щелчка по кнопке `deleteBtn`, которая удаляет последнюю добавленную строку с данными.

### 5. Стилизация (необязательно)

Вы можете добавить стилизацию в файл `styles.css` в корне проекта, чтобы улучшить внешний вид приложения:

