        <h1>Converter YouTube para MP3</h1>
        <input type="text" id="youtubeLink" placeholder="Cole o link do YouTube aqui">
        <button id="convertButton">Converter e Baixar</button>
        <div id="downloadMessage" class="download-message"></div>
    </div>
    <script src="script.js"></script>
</body>
