```

### JavaScript (script.js)
```javascript
document.addEventListener('DOMContentLoaded', function() {
    const youtubeLinkInput = document.getElementById('youtubeLink');
    const convertButton = document.getElementById('convertButton');
    const downloadMessage = document.getElementById('downloadMessage');

    convertButton.addEventListener('click', function() {
        const youtubeLink = youtubeLinkInput.value.trim();
        if (youtubeLink === '') {
            alert('Por favor, cole um link do YouTube.');
            return;
        }

        // Função para extrair o URL do vídeo do YouTube
        function getYouTubeVideoUrl(url) {
            const regex = /(?:https?:\/)?(?:www\.)?(?:youtube\.com|youtu\.be)\/(?:watch\?v=|embed\/)?([^&]+)/;
            const match = url.match(regex);
            return match && match[1] ? match[1] : null;
        }

        const videoUrl = getYouTubeVideoUrl(youtubeLink);
        if (!videoUrl) {
            alert('Link inválido. Por favor, verifique o link do YouTube.');
            return;
        }

        // Função para converter vídeo para MP3 (simulando a conversão)
        function convertToMP3(videoUrl) {
            return new Promise((resolve, reject) => {
                setTimeout(() => {
                    // Simulando a conversão com um delay
                    const mp3Url = `https://example.com/mp3/${videoUrl}.mp3`;
                    resolve(mp3Url);
                }, 2000);
            });
        }

        convertToMP3(videoUrl).then(mp3Url => {
            const a = document.createElement('a');
            a.href = mp3Url;
            a.download = `${videoUrl.split('/').pop()}.mp3`;
            a.click();
            downloadMessage.textContent = 'MP3 baixado com sucesso!';
            downloadMessage.style.color = '#007BFF';
        }).catch(error => {
            console.error('Erro na conversão:', error);
            alert('Ocorreu um erro ao converter o vídeo. Por favor, tente novamente.');
        });
    });
});
```

### Observações:
1. **Extrair URL do YouTube**: A função `getYouTubeVideoUrl` usa uma expressão regular para extrair o ID do vídeo do URL. No entanto, essa abordagem pode não funcionar para todos os casos, especialmente para links de embed ou URLs com parâmetros adicionais. Para uma solução mais robusta, você pode considerar usar uma biblioteca como o `ytdl-core` (para Node.js) ou uma API de extração de vídeo.
2. **Conversão de Vídeo para MP3**: No exemplo acima, a conversão é simulada com um delay de 2 segundos. Em um ambiente real, você precisaria usar uma biblioteca ou serviço de conversão de áudio, como o `ffmpeg` ou uma API de conversão de áudio.
3. **Segurança**: Certifique-se de lidar com links inválidos e erros de forma adequada para evitar problemas de segurança.

Este código fornece uma base para a funcionalidade desejada. Você pode expandir e melhorar conforme necessário para atender às suas necessidades específicas.

