$secondOperand = '';

function appendNumber($number) {
    global $display, $firstOperand;
    $display .= $number;
    $firstOperand .= $number;
}

function setOperation($op) {
    global $display, $operation, $firstOperand, $secondOperand;
    if ($secondOperand !== '') {
        calculate();
    }
    $operation = $op;
    $secondOperand = $firstOperand;
    $firstOperand = '';
    $display = '';
}

function clearDisplay() {
    global $display, $firstOperand, $secondOperand, $operation;
    $display = '';
    $firstOperand = '';
    $secondOperand = '';
    $operation = '';
}

function calculate() {
    global $display, $operation, $firstOperand, $secondOperand;
    $firstOperand = floatval($firstOperand);
    $secondOperand = floatval($secondOperand);

    switch ($operation) {
        case '+':
            $result = $firstOperand + $secondOperand;
            break;
        case '-':
            $result = $firstOperand - $secondOperand;
            break;
        case '*':
            $result = $firstOperand * $secondOperand;
            break;
        case '/':
            if ($secondOperand === 0) {
                $result = 'Error! Division by zero.';
            } else {
                $result = $firstOperand / $secondOperand;
            }
            break;
        default:
            $result = 'Error! Invalid operation.';
    }

    $display = $result;
    $firstOperand = $result;
    $secondOperand = '';
    $operation = '';
}

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    if (isset($_POST['append'])) {
        appendNumber($_POST['append']);
    } elseif (isset($_POST['operation'])) {
        setOperation($_POST['operation']);
    } elseif (isset($_POST['clear']) && $_POST['clear'] === 'true') {
        clearDisplay();
    } elseif (isset($_POST['calculate']) && $_POST['calculate'] === 'true') {
        calculate();
    }
}
