if ($result) {
    // Affichez les informations de géolocalisation
    echo "Adresse IP: " . $ip . "\n";
    echo "Pays: " . $result['country_name'] . "\n";
    echo "Région: " . $result['region_name'] . "\n";
    echo "Ville: " . $result['city'] . "\n";
