// Utilisez une requête HTTP pour obtenir les informations de géolocalisation
$url = "http://api.ipstack.com/$ip?access_key=VOTRE_CLÉ_API";

$ch = curl_init($url);
curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
$response = curl_exec($ch);

if ($response) {
    $data = json_decode($response, true);
    if ($data && isset($data['country_name']) && isset($data['region_name']) && isset($data['city'])) {
        echo "Adresse IP: " . $ip . "\n";
