        <h1>Identification des Étufiants</h1>
        <form action="identify_etufiants.php" method="post">
            <label for="text">Texte:</label>
            <textarea name="text" id="text" rows="10" cols="50" required></textarea><br><br>
            <input type="submit" value="Analyser">
        </form>
        <?php if (isset($result)) : ?>
            <h2>Résultats:</h2>
            <p><?php echo $result; ?></p>
        <?php endif; ?>
    </div>
