```

#### `identify_etufiants.php`
```php
<?php
if ($_SERVER["REQUEST_METHOD"] == "POST") {
    $text = $_POST['text'];

    // Tokenization
    $words = str_split(strtolower($text));

    // Frequency counting
    $word_count = array_count_values($words);

    // Identifying etufiants (words appearing more than 3 times)
    $etufiants = array_filter($word_count, function($count) {
        return $count > 3;
    });

    // Displaying results
    $result = "Étufiants identifiés: " . implode(", ", array_keys($etufiants));
}
?>
